window.NIGHTS.cases[4]={"nr":4,"id":"case04","title":"Athanor","subtitle":"","level":"Mystische Ebene","from":87,"to":112,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":87,"layer":null,"blocks":4},{"id":"das-lebkuchenhaus","kind":"place","title":"DAS LEBKUCHENHAUS","page":88,"layer":null,"blocks":4},{"id":"taeter-opfer-umkehr","kind":"place","title":"TÄTER-OPFER-UMKEHR","page":88,"layer":null,"blocks":4},{"id":"rachels-operation","kind":"place","title":"RACHELS OPERATION","page":89,"layer":null,"blocks":31},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":91,"layer":null,"blocks":8},{"id":"schicht-1-schleckermaeulchen","kind":"layer","title":"SCHICHT 1: SCHLECKERMÄULCHEN","page":92,"layer":null,"blocks":2},{"id":"frau-leckermauls-haus","kind":"place","title":"FRAU LECKERMAULS HAUS","page":92,"layer":"schicht-1-schleckermaeulchen","blocks":28},{"id":"the-bowl","kind":"place","title":"THE BOWL","page":94,"layer":"schicht-1-schleckermaeulchen","blocks":57},{"id":"will-harris-wohnung","kind":"place","title":"WILL HARRIS‘ WOHNUNG","page":98,"layer":"schicht-1-schleckermaeulchen","blocks":18},{"id":"das-schwimmbad","kind":"place","title":"DAS SCHWIMMBAD","page":99,"layer":"schicht-1-schleckermaeulchen","blocks":16},{"id":"charlies-spielzimmer","kind":"place","title":"CHARLIES SPIELZIMMER","page":100,"layer":"schicht-1-schleckermaeulchen","blocks":10},{"id":"schicht-2-suche-nach-brotkrumen","kind":"layer","title":"SCHICHT 2: SUCHE NACH BROTKRUMEN","page":101,"layer":null,"blocks":1},{"id":"foxy-supreme","kind":"place","title":"FOXY SUPREME","page":101,"layer":"schicht-2-suche-nach-brotkrumen","blocks":22},{"id":"das-kandis-drogenlabor","kind":"place","title":"DAS KANDIS-DROGENLABOR","page":103,"layer":"schicht-2-suche-nach-brotkrumen","blocks":23},{"id":"hans-loft","kind":"place","title":"HANS‘ LOFT","page":104,"layer":"schicht-2-suche-nach-brotkrumen","blocks":15},{"id":"auf-dem-trip","kind":"place","title":"AUF DEM TRIP","page":105,"layer":"schicht-2-suche-nach-brotkrumen","blocks":3},{"id":"schicht-3-verloren-im-betondschungel","kind":"layer","title":"SCHICHT 3: VERLOREN IM BETONDSCHUNGEL","page":105,"layer":null,"blocks":1},{"id":"die-alte-aurora-glashuette","kind":"place","title":"DIE ALTE AURORA-GLASHÜTTE","page":105,"layer":"schicht-3-verloren-im-betondschungel","blocks":21},{"id":"lieferung-an-magnum-opus","kind":"place","title":"LIEFERUNG AN MAGNUM OPUS","page":107,"layer":"schicht-3-verloren-im-betondschungel","blocks":5},{"id":"schicht-4-die-lebkuchenver-schwoerung","kind":"layer","title":"SCHICHT 4: DIE LEBKUCHENVER- SCHWÖRUNG","page":108,"layer":null,"blocks":1},{"id":"lebkuchenhaus-enklave","kind":"place","title":"LEBKUCHENHAUS-ENKLAVE","page":108,"layer":"schicht-4-die-lebkuchenver-schwoerung","blocks":56}],"pages":{"87":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN SCHICKSALHAFTER FALL UM SÜSSE VERLOCKUNGEN</b>","sz":20.0,"box":[106.7,776.1,491.4,796.1],"p":87,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"88":{"tab":"","blocks":[{"t":"p","x":"Eine neue Droge kursiert auf den Straßen der Stadt, eine besondere Droge für besondere Menschen wie euch. Es heißt, sie lässt die schönsten Träume wahr werden. Während sie sich verbreitet, häufen sich die Vermisstenfälle schneller, als du sie lösen kannst. Einige der Vermissten tauchen schnell wieder auf, elendig und leer, ohne Lebenswillen. Wenn du in den dunklen, regennassen Gassen der Stadt nach Antworten suchst, wirst du auf deine Träume setzen und dich diesem verlockenden Mittel hingeben?","sz":13.0,"box":[53.9,60.1,285.0,261.6],"p":88,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Athanor</i> ist ein Krimidrama, das einen neuen Trend unter den Rissen der Stadt zum Thema hat: eine wunscherfüllende Substanz. Dieses sogenannte „Kandis“ ist für die SC leicht zugänglich und stellt ihre persönlichen Wünsche und Bestrebungen sowie ihr Privatleben als Risse ins Rampenlicht. Während das Team einen von Mythen betriebenen Drogenring aufspürt, können die SC diesen Fall als Täter:innen, Opfer der Gier oder als beides durchspielen.","sz":9.5,"box":[53.9,272.1,286.3,381.6],"p":88,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"Die verlockende Spur führt zu einer modernen Hexe, die den Mythos von Rissen ernten will. Das mystische Motiv hinter dem Drogenring kommt erst am Ende des Falles zum Vorschein und steht mit dem Rest der mystischen Ebene in Verbindung.","sz":9.5,"box":[53.9,390.3,279.5,449.8],"p":88,"i":2,"sec":"titel-und-pitch"},{"t":"h","x":"DAS LEBKUCHENHAUS","sz":16.0,"box":[53.9,501.8,201.1,517.8],"p":88,"i":3,"skip":true,"sec":"das-lebkuchenhaus"},{"t":"p","x":"Als der Alchemist Armand Kai das Verfahren zur Erweckung neuer Risse perfektionierte, suchte er nach einer Möglichkeit, ihnen ihre Mythos-Kräfte zu entziehen. Nachdem er Briefe und Nachrichten an diverse verrückte Wissenschaftler und Zauberer der Riss- Subkultur geschickt hatte, verwies man ihn an <b>Rosina Leckermaul</b> (die Hexe aus <i>Hänsel und Gretel</i>), die Expertin darin war, Menschen in ihrem Ofen zu rösten und ihnen die Essenz auszusaugen. Gemeinsam bauten Armand und Leckermaul in einer alten Glashütte (die ursprüngliche Aurora-Glashütte, s. <i>Splitter</i>, S. 62) einen <b>Mythos-Extraktionsofen</b>. Leckermaul erschuf eine wunscherfüllende Substanz namens <b>Kandis</b>, mit der sie armen Seelen in ihren Ofen lockte.","sz":9.5,"box":[53.9,521.7,286.1,693.7],"p":88,"i":4,"sec":"das-lebkuchenhaus"},{"t":"p","x":"Sobald Kandis einen Riss in die <u>Lebkuchenhaus-Enklave</u> gelockt hatte, fand er sich in einem magischen Käfig wieder und kam in den Ofen. Darin gebratene Risse starben nicht, sondern verloren ihre Kräfte und wurden wieder zu Schläfer:innen, denen jeglicher Mythos, selbst ein ruhender, fehlte. Sie verloren, was sie beseelt hatte, und fühlten sich leer und ohne Sinn. Die Essenz ihrer Mythos-Kräfte verwandelte sich in <b>Ichor</b>, den Leckermaul im Gegenzug für einige wertvolle Tinkturen zu Armands Herrenhaus brachte.","sz":9.5,"box":[309.0,59.9,541.1,181.9],"p":88,"i":5,"sec":"das-lebkuchenhaus"},{"t":"p","x":"Die Operation verlief meist reibungslos. Dank des Nebels vergaßen die Opfer ihre Sucht und Entführung, und niemand stellte Fragen. Ab und zu ging der Kochvorgang schief und hinterließ den ehemaligen Riss als geistlose Kreatur, die neutralen weißen Ichor ausstieß. Leckermaul behielt die „Ausschussware“, wegen der rostbraunen und weißen Färbung <b>Lebkuchenmänner</b> genannt, und setzte sie zur Verteidigung der Fabrik ein: Sie fingen jeden spionierenden oder entkommenen Riss ein und ernährten sich von dessen Essenz.","sz":9.5,"box":[309.0,190.6,539.7,312.6],"p":88,"i":6,"sec":"das-lebkuchenhaus"},{"t":"h","x":"TÄTER-OPFER-UMKEHR","sz":16.0,"box":[309.0,328.3,465.6,344.3],"p":88,"i":7,"skip":true,"sec":"taeter-opfer-umkehr"},{"t":"p","x":"Leckermaul hatte Pech: Ihr Kandis erregte die Aufmerksamkeit zweier junger und auf der Straße lebenden Risse, der Geschwister <b>Hans und Rachel Woods</b>. Das Duo fiel auf Kandis herein und geriet in Gefangenschaft. Aber als die Hexe Rachel in den Ofen stieß, nutzte diese Kräfte, um den Platz mit Leckermaul zu tauschen, die dann verbrannte und den Ofen stoppte.","sz":9.5,"box":[309.0,348.2,539.7,432.7],"p":88,"i":8,"sec":"taeter-opfer-umkehr"},{"t":"p","x":"Als die <b>Magnum-Opus-Kultist:innen</b> (Armands Schüler:innen) den Ichor einsammeln kamen, schloss Rachel einen Deal mit ihnen ab: der Alchemist sollte ihr die Lebkuchenhexen-Tinktur geben und sie würde dafür, mit Hilfe von Leckermauls Tinktur-Kräften, weiterhin den Ofen für ihn betreiben. Mit mehr Leistung. Woods wollte die Mythoskräfte ihres Bruders (die Fähigkeit, immer nach Hause zu finden) in die Drogen einbauen, um Kandis-Nutzer zu ihr zu führen, indem sie einer Spur aus Kieseln zur Enklave folgten.","sz":9.5,"box":[309.0,441.4,540.6,563.4],"p":88,"i":9,"sec":"taeter-opfer-umkehr"},{"t":"p","x":"Armand akzeptierte, stellte die Lebkuchenhexen-Tinktur her, und der Ofen war unter Rachel Woods‘ Leitung einsatzbereit. Rosina, nun eine Schläferin, wurde nach Hause geschickt, wo sie in Trostlosigkeit den ganzen Tag aus dem Fenster starrt. Hans, der andere Pläne und ein schlechtes Gewissen hatte, wurde süchtig nach Kandis und versuchte, alles zu vertuschen.","sz":9.5,"box":[309.0,572.0,540.7,656.5],"p":88,"i":10,"sec":"taeter-opfer-umkehr"}],"size":[595.276,841.89]},"89":{"tab":"","blocks":[{"t":"h","x":"RACHELS OPERATION","sz":16.0,"box":[53.9,341.5,194.5,357.5],"p":89,"i":0,"skip":true,"sec":"rachels-operation"},{"t":"p","x":"Rachel stellt in der <u>Lebkuchenhaus-Enklave</u> reines Kandis her. Die Substanz wird zum <u>Kandis-Drogenlabor</u> der <b>Hinterlistigen Nagas</b> transportiert, einer Bande, die sie mit echten Süßigkeiten mischt und verpackt. Das Kandis wird dann über Leckermauls früheres Händlernetz vertrieben, das <u>Foxy Supreme</u> (die Teumessische Füchsin, eine uneinholbare Riesenfüchsin aus Theben) leitet, und zwar mit Hilfe berührter Lakai:innen, die Risse von Schläfer:innen unterscheiden können und nur an erstere verkaufen (für Schläfer:innen ist Kandis eine Süßigkeit ohne Wirkung).","sz":9.5,"box":[53.9,361.4,282.6,495.9],"p":89,"i":1,"sec":"rachels-operation"},{"t":"sh","x":"<b>NEUE OPFER</b>","sz":10.0,"box":[54.3,509.5,122.9,519.5],"p":89,"i":2,"sec":"rachels-operation"},{"t":"p","x":"Die Opfer erwerben Kandis so, wie sie illegale Freizeitdrogen kaufen würden. Kandis erfüllt ihre Wünsche bis zu einem gewissen Grad, aber das Ergebnis ist immer unbefriedigend oder flüchtig, so dass sie nach mehr suchen. Dann zeigt ihnen Hans‘ Heimkehrzauber den Weg zum Ofen. Sie verschwinden für 24-48 Stunden und tauchen danach lust- und kraftlos wieder auf.","sz":9.5,"box":[53.9,525.0,285.1,609.5],"p":89,"i":3,"sec":"rachels-operation"},{"t":"p","x":"Zuletzt hat der Ofen dank Rachels Übermut, der Tinktur und Hans‘ Zauber die Produktion gesteigert.","sz":9.5,"box":[53.9,618.2,280.6,640.2],"p":89,"i":4,"sec":"rachels-operation"},{"t":"p","x":"Seine jüngsten Opfer sind:","sz":9.5,"box":[53.9,648.9,165.9,658.4],"p":89,"i":5,"sec":"rachels-operation"},{"t":"p","x":"• <b>Immer noch auf Kandis</b>: <b>Charlie Littles</b>, ein 7-jähriger Riss der Voodoo-Puppe (der Popkultur-Version, die wenig mit realem Voodoo zu tun hat), der Kandis von einem Nutzer gestohlen hat, um mehr Spielzeug zu bekommen. Bald ist es aufgebraucht, also sucht er nach Erwachsenen, um an mehr zu kommen.","sz":9.5,"box":[53.9,669.9,285.0,741.9],"p":89,"i":6,"sec":"rachels-operation"},{"t":"p","x":"• <b>Vermisst</b>: <b>Will Harris</b>, alleinerziehende Mutter aus dem Arbeiterviertel, war der Riss Wilhelm Tells (des Schweizer Volkshelden, der seinem Sohn einen Apfel vom Kopf schoss). Sie benutzte Kandis, um ihrem Sohn und sich ein besseres Leben zu geben, doch dann landete sie im Ofen. Sie wird innerhalb von 24 Stunden auftauchen, ohne Kräfte und Erinnerung.","sz":9.5,"box":[309.0,365.8,539.8,450.3],"p":89,"i":7,"sec":"rachels-operation"},{"t":"p","x":"• <b>Ohne Kräfte zurückgekehrt</b>: <b>Juan Delamar</b>, der frühere Riss Ningyos (einer japanischen Fischmenschen-Kreatur) und Goldmedaillengewinner im Schwimmen, kam nach zwei Tagen machtlos nach Hause. Der Trainer seines Schwimmteams ist ratlos.","sz":9.5,"box":[309.0,459.0,536.1,518.5],"p":89,"i":8,"sec":"rachels-operation"},{"t":"p","x":"Es gibt noch viele weitere Ex-Risse, die ohne Kräfte zurückgekehrt sind, aber ihre Geschichten spielen in diesem Fall keine Rolle. Darüber hinaus sind mit Leckermaul und Hans zwei (potenzielle) Opfer unterwegs, die mit dem üblichen Muster brechen:","sz":9.5,"box":[309.0,524.3,533.6,583.8],"p":89,"i":9,"sec":"rachels-operation"},{"t":"p","x":"• <b>Nahm kein Kandis, ist aber ohne Kräfte zurückgekehrt</b>: <b>Rosina Leckermaul</b>, eine alte Dame, einst Drogenproduzentin und der Riss der Hexe aus Hänsel und Gretel, ist nun ans Haus gefesselt und verbringt ihre Tage damit, ins Leere zu starren.","sz":9.5,"box":[309.0,595.3,534.4,654.8],"p":89,"i":10,"sec":"rachels-operation"},{"t":"p","x":"• <b>Unverändert zurückgekehrt</b>: <b>Hans Woods</b>, ein DJ, dessen Ruhm durch Kandis in die Höhe schnellte, ist der einzige Abhängige, der mit mehr Kandis zurückkehrte und die Kräfte behielt.","sz":9.5,"box":[309.0,663.5,538.4,710.5],"p":89,"i":11,"sec":"rachels-operation"},{"t":"p","x":"Rachel lebt jetzt in der <u>Lebkuchenhaus-Enklave.</u>","sz":9.5,"box":[309.0,716.3,512.7,725.8],"p":89,"i":12,"sec":"rachels-operation"}],"size":[595.276,841.89]},"90":{"tab":"","blocks":[{"t":"h","x":"KANDIS","sz":23.0,"box":[53.9,63.4,126.7,86.4],"p":90,"i":0,"sec":"rachels-operation"},{"t":"p","x":"Kandis ist eine Designerdroge und dafür geschaffen, Risse in den Ofen zu locken, indem es für eine kurze Zeit die Wünsche der Konsument:innen erfüllt. Kandis macht nicht süchtig, ist also keine Droge im eigentlichen Sinne. Es ist die Sucht nach Wunscherfüllung, die Nutzende dazu bringt, mehr zu wollen. In der Glasfabrik kommt Kandis erst richtig zum Tragen: Die Einnahme ermöglicht, die <u>Lebkuchenhaus-Enklave</u> zu betreten und sperrt ankommende Risse in einen magischen Käfig, der sie auf den Ofen vorbereitet.","sz":9.5,"box":[53.9,94.9,283.8,216.9],"p":90,"i":1,"sec":"rachels-operation"},{"t":"p","x":"Aktuell enthält Kandis einige Mythos-Kräfte Hans Woods‘ und zeigt Konsument:innen auf der Suche nach mehr einen Weg aus Kieseln, der zur <u>Aurora-Glashütte</u> und in die <u>Lebkuchenhaus-Enklave</u> führt. Reine Kandis – ein blaues Pulver – wird im <u>Kandis-Drogenlabor</u> zu Süßigkeiten und mit dem dekorativen Buchstaben „K“ wie aus einem Märchenbuch versehen.","sz":9.5,"box":[53.9,225.5,286.3,310.0],"p":90,"i":2,"sec":"rachels-operation"},{"t":"sh","x":"<b>ANWENDUNG VON KANDIS</b>","sz":10.0,"box":[54.3,323.6,201.6,333.6],"p":90,"i":3,"sec":"rachels-operation"},{"t":"p","x":"Wenn Risse Kandis nehmen, erfüllt es ihren größten Wunsch. Das kann ein Lottogewinn sein, eine Liebeserklärung, der Bankrott einer Person usw. Cineastisch hat Kandis begrenzte Macht. Es kann Wünsche in Form eines Geschichten-Markers verwirklichen, vermag also nicht, eine wichtige Figur zu verletzen oder zu ändern, sondern kann die Realität in die Richtung weisen (z. B. eine Waffe erschaffen, mit der man jemanden erschießen kann). Sei großzügig mit dem, was Kandis kann. Z. B. kannst du einem SC, dessen Geliebte gestorben ist, erlauben, sie für kurze Zeit zurückzubringen.","sz":9.5,"box":[53.9,339.2,285.7,473.7],"p":90,"i":4,"sec":"rachels-operation"},{"t":"p","x":"Wenn man Kandis nutzt, und etwas wünscht, das die Kraft übersteigt, verpufft es und verursacht rein kosmetische Realitätsstörungen. Konsument:innen meinen, mehr zu brauchen, um den Wunsch zu erfüllen. Kandis kann man gewollt nicht strecken.","sz":9.5,"box":[53.9,482.4,277.5,541.9],"p":90,"i":5,"sec":"rachels-operation"},{"t":"p","x":"Kandis verliert nach kurzer Zeit seine Wirkung, was je nach Wunsch und Spielaufhänger Stunden oder Tagen sein können. Dann versagen oder verblassen die Wünsche, z. B. funktionieren Gegenstände nicht mehr, der gesellschaftliche Einfluss schwindet usw. Auch hier haben Konsument:innen das Gefühl, mehr zu brauchen, um den Wunsch aufrechtzuerhalten (s. S. Auf dem Trip).","sz":9.5,"box":[53.9,550.5,283.3,647.5],"p":90,"i":6,"sec":"rachels-operation"},{"t":"p","x":"<b>Verwende Kandis als cineastisches Mittel, um die Geheimnisse und Identitäten der Teammitglieder zu lüften und ihre tiefsten oder oberflächlichsten Sehnsüchte ins Rampenlicht zu stellen.</b>","sz":9.5,"box":[53.9,656.3,278.5,703.3],"p":90,"i":7,"sec":"rachels-operation"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER KANDIS</b>","sz":10.0,"box":[54.3,716.8,248.1,726.8],"p":90,"i":8,"sec":"rachels-operation"},{"t":"p","x":"Ein SC mit passender Ausbildung, einer Kandis-Probe und Zeit im Labor kann Hinweise sammeln, während Risse mit Kenntnissen magischer Künste, besonders Alchemie und Kräuterkunde, mehr erfahren können.","sz":9.5,"box":[53.9,732.4,279.8,779.4],"p":90,"i":9,"sec":"rachels-operation"},{"t":"card","x":"Das Produkt ist eine mit einer unbekannten psychoaktiven Substanz versetze Süßigkeit","sz":null,"k":"yellow","box":[309.3,54.1,541.7,87.8],"p":90,"i":10,"sec":"rachels-operation"},{"t":"card","x":"Rauschgiftspuren an der Verpackung zeigen, dass Kandis mit anderen Drogen gehandelt wird, wahrscheinlich von einem lokalen Drogenring. Ein guter Ermittler, der mehrere Hinweise ausgibt, könnte die Spur mit einem bekannten Drogenkartell, den Hinterlistigen Nagas, in Verbindung bringen und so die Suche nach dem <u>Kandis-Drogenlabor</u> einschränken.","sz":null,"k":"yellow","box":[309.3,97.3,541.7,205.9],"p":90,"i":11,"sec":"rachels-operation"},{"t":"card","x":"<b>Ein Blick hinter den Nebel</b> oder die Anwendung legendärer Fertigkeiten lässt erkennen, dass die Substanz niedere Wunscherfüllungsmagie enthält. Eine gut formulierte Hinweisfrage könnte zeigen, dass mit der Erfüllung Bedingungen verbunden sind. Welche ist schwer zu sagen, da als Antwort nur Visionen des Lebkuchenhauses entstehen.","sz":null,"k":"yellow","box":[309.3,215.1,541.7,324.0],"p":90,"i":12,"sec":"rachels-operation"},{"t":"card","x":"<b>Der Blick hinter den Nebel</b> kann eine Verbindung zu Hans‘ Mythos (mondbeschienene Kieselsteine) oder der Hexe aus Hänsel und Gretel (brennender Ofen) aufzeigen.","sz":null,"k":"yellow","box":[309.3,333.2,541.7,392.0],"p":90,"i":13,"sec":"rachels-operation"},{"t":"p","x":"Um alle Eigenschaften aufzudecken, muss man Zeit und Ressourcen investieren. Gib Kandis <i>unbekannte Substanz</i> und <i>versteckte Magie</i>, um Untersuchung zu erschweren. Wird untersucht, passe die Hinweise an die genutzten Fähigkeiten und/oder Gerätschaften an.","sz":9.5,"box":[309.0,410.4,531.4,482.4],"p":90,"i":14,"sec":"rachels-operation"},{"t":"sh","x":"<b>SPIELEFFEKTE</b>","sz":10.0,"box":[309.4,496.0,389.0,506.0],"p":90,"i":15,"sec":"rachels-operation"},{"t":"p","x":"Wenn ein SC Kandis nimmt, erhält er einen fortlaufenden Geschichten-Marker, der den erfüllten Wunsch beschreibt, z. B. <i>Millionär</i>. Als fortlaufenden Marker kann ihn ausbrennen. Für Bedrohungen wähle harte SL-Aktionen, die ihrem Wunsch entsprechen.","sz":9.5,"box":[309.0,511.5,537.8,571.0],"p":90,"i":16,"sec":"rachels-operation"},{"t":"p","x":"<b>Behalte im Auge, welche Charaktere Kandis nehmen.</b> Sie können die <u>Lebkuchenhaus-Enklave</u> betreten, Nicht-Konsument:innen nicht. Außerdem bekommt jeder Charakter, der Kandis konsumiert hat, beim Betreten der Enklave <t>im Käfig 4</t>, ohne <b>Sich der Gefahr zu stellen</b>. Wenn die SC diesen Effekt entdecken, ehe sie die Enklave betreten, und versuchen, ihn zu verhindern, müssen sie <b>Das Blatt wenden</b> und 1 Momentum für eine spezielle Effektverbesserung von 10+ ausgeben, um einen Effekt, der nur potenziell vorhanden ist, aufzuheben. Kandis zu manipulieren, um die Enklave ohne negative Auswirkungen zu betreten, erfordert einen SC mit entsprechenden Fähigkeiten und <b>Jetzt reicht’s!</b> mit einem signifikanten oder unumkehrbaren Opfer (s. S. Betreten der Enklave, S. 105).","sz":9.5,"box":[309.0,579.8,539.1,776.7],"p":90,"i":17,"sec":"rachels-operation"}],"size":[595.276,841.89]},"91":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,475.8,122.3,489.8],"p":91,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,498.1,170.2,521.1],"p":91,"i":1,"skip":true},{"t":"p","x":"Du kannst das Team folgendermaßen in den Fall einbeziehen:","sz":9.5,"box":[53.9,529.5,277.5,551.5],"p":91,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Berichte über eine neue Droge</b>: Das Team erfährt, dass jemand aggressiv eine neue Droge vertreibt. Diese Information könnte von Unterweltkontakten, aufgeweckten Polizeibeamten (wie Officer Das, s. <i>Der sanfte Tod</i>) oder dem besorgten <b>Eddie Traumzeit</b>, Besitzer der <u>„Bowl“,</u> eines Fightclubs für Risse, stammen. Der Informant weiß nicht viel über die neue Droge. Es kann sich sogar um eine Schläfer:in handeln, die nur Gerüchte streut. Auf der Straße heißt es, diese Droge lasse Wünsche wahr werden und sei unter dem Markennamen „Kandis“ im Handel. Unwahrscheinlich ist, dass Kriminelle auf Nachfrage den Namen Rosina Leckermaul als die Dealerin nennen, was auf <u>Frau Leckermauls Haus</u> hinweist.","sz":9.5,"box":[53.9,563.1,284.6,735.1],"p":91,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Risse verschwinden oder verlieren ihre Kräfte</b>: Jemand könnte das Team alarmieren, wenn weiter-","sz":9.5,"box":[53.9,743.7,276.6,765.7],"p":91,"i":4,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"hin Risse verschwinden und ohne Kräfte wieder auftauchen. Ein Besucher des <u>„Bowl“,</u> der Will Harris kennt, könnte um Hilfe bei der Suche nach ihr bitten <u>(Will Harris‘ Wohnung).</u> Trainer <b>Bradley Ferrell</b> (ein Schläfer), Juan Delamars Schwimmtrainer, könnte das Team ins <u>Schwimmbad</u> einladen und es dort um Hilfe bitten, weil er wissen möchte, was mit seinem besten Schwimmer passiert ist. Es können Risse verschwinden und entkräftet zurückkehren, die in Nebenrollen aufgetreten sind. Das Team könnte außerdem einen Bösewicht oder eine Nemesis ihrer Kräfte berauben wollen – dann wird es persönlich.","sz":9.5,"box":[317.5,465.3,539.0,612.3],"p":91,"i":5,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Kandis-Konsument:innen</b>: Risse, die gerade erst mit Kandis begonnen haben, bewirken wilde Veränderungen in der Realität und erregen möglicherweise die Aufmerksamkeit des Teams. Gelangweilte Vorstadthausfrauen klettern über Nacht an die Spitze der gesellschaftlichen Leiter, während Geschäftsleute mit überraschenden Gewinnen die Börse aufmischen. Dieses unheimliche Glück ist in der Regel von kurzer Dauer und veranlasst Konsument:innen, sich mehr Kandis zu besorgen. Im Idealfall bietet ein Dealer einem SC oder einer der Nebendarsteller der Kampagne Kandis, was die betroffene Person in die","sz":9.5,"box":[309.0,621.0,541.4,768.0],"p":91,"i":6,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"92":{"tab":"","blocks":[{"t":"p","x":"Sucht treibt und zu Rachel Woods‘ nächstem Opfer macht. Vielleicht erfährt das Team von einem Kind, das jedes Spielzeug bekommen kann, das es will – eine Spur, die zu <u>Charlies Spielzimmer</u> führt.","sz":9.5,"box":[62.4,59.9,279.1,106.9],"p":92,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Hans Woods</b>, der zunehmend Gewissensbisse wegen seiner und Rachels Beteiligung an der Sache verspürt, könnte versuchen, das Team zu manipulieren, damit es die Aktivitäten seiner Schwester beendet. Er will, dass sie aus dem Ichor-Geschäft aussteigt, hat aber Angst, sie zur Rede zu stellen, und will Vergeltungsmaßnahmen von Magnum Opus vermeiden. Mehr als alles andere will er seine Schwester retten. Hans gibt sich als Leckermauls Enkel aus und sagt, seine Großmutter sei nicht mehr das, was sie mal war: Sie hat sich über Nacht von einer lebenslustigen Frau in einen Zombie verwandelt (er weist das Team auf <u>Frau Leckermauls Haus</u> hin). Dann beobachtet er aus sicherem Abstand die Ermittlungen, bis sie zu ihm zurückführen oder das Team die Glashütte findet. <b>Beachte, dass es Fingerspitzengefühl beim Verteilen von Hinweisen und ein Pokerface erfordert, das Team in einem so frühen Stadium des Falles mit Hans zu konfrontieren.</b>","sz":9.5,"box":[53.9,115.6,286.2,350.2],"p":92,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[309.0,69.1,376.0,83.1],"p":92,"i":2,"skip":true,"sec":"schicht-1-schleckermaeulchen"},{"t":"h","x":"SCHLECKERMÄULCHEN","sz":23.0,"box":[309.0,91.4,533.5,114.4],"p":92,"i":3,"skip":true},{"t":"p","x":"Diese Schicht präsentiert mehrere Schauplätze und Fälle von Konsument:innen, die das Team untersuchen kann. Um das Tempo zu steuern, kannst du Hinweise, die zur zweiten Schicht führen, zurückhalten und stattdessen auf Orte in dieser Schicht hinweisen, damit sich das Team ein Bild von der Kandis-Epidemie machen kann. Wenn das Team in eine Sackgasse gerät, kannst du weitere Aufhänger verwenden, um sie zu den restlichen Schauplätzen in Schicht 1 zu führen.","sz":9.5,"box":[309.0,122.9,540.5,232.4],"p":92,"i":4,"sec":"schicht-1-schleckermaeulchen"},{"t":"h","x":"FRAU LECKERMAULS HAUS","sz":16.0,"box":[334.8,249.0,512.1,265.0],"p":92,"i":5,"skip":true,"sec":"frau-leckermauls-haus"},{"t":"ro","x":"Vögel zwitschern und pfeifen um euch herum, als ihr durch das Tor im weißen Zaun vor dem Altstadthaus in einen blühenden Garten tretet. Der Himmel ist fast wolkenlos, wenige Schäfchenwolken treiben träge dahin. Ihr seht Frau Leckermaul am Fenster sitzen, die euch entgegenschaut und einen Schluck aus einer dampfenden Tasse trinkt. Erst als ihr näher kommt, bemerkt ihr, dass sie nicht euch ansieht, sondern einfach nur ins Leere starrt.","sz":9.0,"box":[317.5,267.4,538.9,384.4],"p":92,"i":6,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Frau Leckermaul bewohnt ein hübsches kleines Häuschen, das von Zaun und Garten umgeben in einem Wohnviertel der Altstadt liegt. Die Szene dient dazu Spannung aufzubauen und eine Vorahnung zu geben, indem sie ein Opfer präsentiert, das seine Kräfte verloren hat. An dieser Stelle wird das Team bei den Nachforschungen vermutlich nicht Leckermauls Verstrickungen in den Fall aufdecken, aber es könnte später zurückkehren, um die Spur weiter zu verfolgen.","sz":9.5,"box":[309.0,393.4,540.2,502.9],"p":92,"i":7,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Rosina Leckermaul ist eine ältere Frau, die den Lebenswillen verloren zu haben scheint und sich in einer tiefen Depression befindet. Sie reagiert nicht, wenn man sie anspricht, murmelt höchstens vor sich hin (ohne nützliche Informationen). Leckermaul bewältigt irgendwie den Alltag, tut das Nötigste, um zu überleben und verbringt ihre Zeit hauptsächlich damit, aus dem Fenster in den Garten zu starren.","sz":9.5,"box":[309.0,511.6,539.0,608.6],"p":92,"i":8,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Bis vor einem Monat war Leckermaul die Lebkuchenhexe und eine niederträchtige Drogenhändlerin, die mit Magnum Opus zusammenarbeitete. Sie unterhielt dieses Haus als Fassade, um sich die Polizei vom Leib zu halten. Dann hat die kleine Teufelin Rachel Woods sie reingelegt und durch den Ofen, den sie selbst gebaut hat, den Mythos geraubt. Sie verwandelte sich in eine Schläferin und vergaß alles. Das Letzte, woran sie sich erinnert, ist, dass sie nach Hause kam, aber sie kann sich nicht erinnern woher. Leckermauls frühere Angestellte erinnern sich nur an sie, wenn sie Risse sind. Die Schläfer:innen ihres Drogenrings, vor allem die Hinterlistigen Nagas, haben sie längst vergessen.","sz":9.5,"box":[309.0,617.2,537.3,776.7],"p":92,"i":9,"sec":"frau-leckermauls-haus"}],"size":[595.276,841.89]},"93":{"tab":"","blocks":[{"t":"h","x":"RETTUNG DER OPFER DES OFENS","sz":14.0,"box":[65.2,73.7,215.6,87.7],"p":93,"i":0,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Die Opfer des Ofens haben dauerhaft einen Zustand der Stufe 6. Möglichkeiten, ihnen den Mythos wiederzugeben, meist mit der Tinktur ihres Mythos, sind in Die mystische Ebene (s. S. 84) beschrieben. Wenn ein SC Auswirkungen des Nebels lindern kann, könnte er die Erinnerungen des Opfers wiederherstellen, nicht aber die Kräfte. Dies sollte einem signifikanten <b>Jetzt reicht’s!</b>-Opfer entsprechen, wenn das Ziel sich an nützliche Details erinnern, oder einem größeren, wenn es wichtige Informationen preisgeben soll.","sz":9.0,"box":[65.2,100.3,273.8,229.3],"p":93,"i":1,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Leckermaul ist eine nette, vergessliche alte Oma.</b> Dies widerspricht Berichten über den alten Lebensstil (Hans) und der Arbeit als Dealerin (Straßenkontakte) und wirft Fragen auf.","sz":null,"k":"yellow","box":[54.1,254.0,286.6,312.8],"p":93,"i":2,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Im verschlossenen Keller</b> steht eine seltsame Sammlung von Käfigen, einige groß genug für Menschen, was darauf hindeuten könnte, dass Leckermaul mehr ist, als man sieht. Sie sind seit Wochen, vielleicht Monaten ungenutzt.","sz":null,"k":"yellow","box":[54.1,322.0,286.6,393.4],"p":93,"i":3,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>In der Waschmaschine</b> ist eine schwarze Lederjacke und Lederhose und ein weißes Tank- Top in Leckermauls Größe, die nach Rauch riechen. Sie kennt die Klamotten nicht.","sz":null,"k":"yellow","box":[54.1,402.6,286.6,461.4],"p":93,"i":4,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Leckermauls Telefonverbindungen des zurückliegenden Monats</b> könnten sie mit <u>Foxy Supreme</u> oder den Hinterlistigen Nagas im <u>Kandis-Drogenlabor</u> in Verbindung bringen. Da der Nebel Zeit hatte, die Informationen zu zerstören, könnten sie <t>verfälscht 3</t> sein.","sz":null,"k":"yellow","box":[54.1,470.6,286.6,554.4],"p":93,"i":5,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Jenseits des Nebels</b> ist Leckermaul eine Schläferin, das Haus hat keinen Mythos. Allerdings haftet ihr eine schwache Spur des Mythos der Lebkuchenhexe an. Es ist nicht <i>ihr</i> Mythos, sondern kommt aus einer anderen Quelle (s. S. Textkasten „Die Ofenspur“).","sz":null,"k":"yellow","box":[54.1,563.6,286.6,647.4],"p":93,"i":6,"sec":"frau-leckermauls-haus"},{"t":"card","x":"Wenn man Leckermauls Schritte magisch zurückverfolgt oder ihre Vergangenheit magisch erforscht, sieht man sie mit einer jüngeren Frau im weißen Pelzmantel und einem glitzernden Minikleid nach Hause kommen. <u>(Foxy Supreme,</u> die früher für sie arbeitete und sie nach dem Vorfall im Ofen nach Hause brachte).","sz":null,"k":"yellow","box":[54.1,656.4,286.6,752.8],"p":93,"i":7,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Wenn Hans zugegen ist, wird er bei seiner Geschichte bleiben, dass er Leckermauls Enkel ist und sich seit dem Vorfall um sie kümmert.","sz":9.5,"box":[309.0,59.9,533.7,94.4],"p":93,"i":8,"sec":"frau-leckermauls-haus"},{"t":"card","x":"Bis vor sechs Wochen war Hans ein drittklassiger DJ, der ein oder zwei Sets pro Monat in obskuren Bars hatte. Dann wurde er entdeckt und legt nun in den angesagtesten Clubs auf.","sz":null,"k":"yellow","box":[309.3,100.8,541.7,159.8],"p":93,"i":9,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Hans kennt sich im Haus nicht so gut aus</b>, wie man es von einem regelmäßigen Besucher erwarten würde. Er findet keine Gläser, um dem Team Getränke anzubieten, und verirrt sich bei der Hausführung.","sz":null,"k":"yellow","box":[309.3,169.1,541.7,240.2],"p":93,"i":10,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Wer Hans gut einschätzt merkt, dass er ganz oder teilweise lügt</b> und eine geheime Agenda hat. <b>Sagt man ihm das auf den Kopf zu</b>, wird er Hinweise geben, um vertrauenswürdig zu erscheinen und seine Tarnung aufrechtzuerhalten: Er wird „zugeben“, mehr Kandis zu suchen und gekommen zu sein, weil Leckermaul das Zeug früher hergestellt hat. <b>Wenn man ihn zum Reden zwingt</b>, verrät er die Person, die das Kandis verkauft <u>(Foxy Supreme),</u> um seine Beteiligung an den Geschäften zu verbergen.","sz":null,"k":"yellow","box":[309.3,249.4,541.7,395.7],"p":93,"i":11,"sec":"frau-leckermauls-haus"},{"t":"card","x":"<b>Die Verfolgung Hans‘</b> könnte zum <u>Bowl-Fight Club</u> oder zu seinem <u>Loft</u> führen.","sz":null,"k":"yellow","box":[309.3,404.9,541.7,438.6],"p":93,"i":12,"sec":"frau-leckermauls-haus"},{"t":"h","x":"DIE OFENSPUR","sz":14.0,"box":[320.3,474.1,387.9,488.1],"p":93,"i":13,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Schwach hinterlässt der Ofen einen Mythos-Fußabdruck auf den Rissen, die er in Schläfer:innen verwandelt. Jenseits des Nebels manifestiert sich dies als Vision eines brennenden Ofens. Es ist nur ein Detail, aber eines, das den Fall aufklären könnte und das aufmerksame Spieler mitbekommen sollten.","sz":9.0,"box":[320.3,500.7,526.8,569.7],"p":93,"i":14,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Wenn das Team zum ersten Mal ein Ofen-Opfer untersucht und dabei <b>jenseits des Nebels</b> schaut oder arkane Ermittlungsfähigkeiten einsetzt, kannst du ihm den Hinweis geben, ihn aber vage halten. Bei späteren Opfern solltest du den Hinweis nur geben, wenn ein SC speziell danach sucht.","sz":9.0,"box":[320.3,578.3,527.1,647.3],"p":93,"i":15,"sec":"frau-leckermauls-haus"}],"size":[595.276,841.89]},"94":{"tab":"","blocks":[{"t":"threat","stars":"★","name":"HANS","spectra":"","items":[],"box":[62.4,57.5,103.0,73.6],"p":94,"i":0,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Hans ist ein großer, energiegeladener junger Mann mit einem hellen Haarschopf, den man meist in Surferklamotten sieht und der einen Rucksack mit seiner DJ-Ausrüstung mit sich herumträgt. Seine heisere Stimme und Kifferjargon lassen vermuten, dass er mit Drogen mehr als nur experimentiert hat.","sz":9.0,"box":[62.4,80.6,277.4,149.6],"p":94,"i":1,"sec":"frau-leckermauls-haus"},{"t":"p","x":"Hans‘ Kräfte ermöglichen es ihm, den Weg „nach Hause“ zu finden, wo immer er sich befindet, so dass er sich nie verirren kann. Derzeit ist sein emotionales „Zuhause“ an zwei verschiedenen Orten in der Stadt: in seinem Loft und bei seiner Schwester. So kann er magisch den Weg zur und von der Lebkuchenhaus- Enklave „finden„. Da Rachel die Enklave nie verlässt, sind seine beiden Zuhauses fest verankert, so dass er nahezu resistent gegen Orientierungslosigkeit ist.","sz":9.0,"box":[62.4,158.6,275.6,263.6],"p":94,"i":2,"sec":"frau-leckermauls-haus"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / FANGEN 3 / DESORIENTIEREN –</b>","sz":12.0,"box":[62.4,274.1,245.9,298.1],"p":94,"i":3,"sec":"frau-leckermauls-haus"},{"t":"p","x":"• <b>Gassenratte</b>: Wenn Hans anfängt zu rennen, gib ihm <i>Gassenratte</i>. • <b>Wahre Liebe</b>: Wenn du versuchst, Hans dazu zu bringen, seine Schwester zu verraten oder zu gefährden, bekommt er <t>wahre Liebe 5</t>.","sz":9.0,"box":[62.4,302.6,264.9,359.6],"p":94,"i":4,"sec":"frau-leckermauls-haus"},{"t":"p","x":"• Süßigkeiten essen und sich wegwünschen (<b>Ihnen etwas verweigern, das sie wollen</b>) • Jemanden in den Gassen abhängen (einen <i>Fangen</i>- Zustand um 2 Stufen reduzieren) • Jemandem Kandis geben (<b>Die Dinge richtig kompliziert machen</b>) • Darüber reden, dass Kandis das Beste ist, was es gibt (<t>in Versuchung 2</t>) • Vermuten, dass das Team ihm oder seiner Schwester etwas antun will, und <t>unkooperativ 2</t> werden","sz":9.0,"box":[62.4,368.6,272.6,485.6],"p":94,"i":5,"sec":"frau-leckermauls-haus"},{"t":"p","x":"• Seinen Rucksack nach Kandis durchwühlen","sz":9.0,"box":[62.4,494.6,243.3,503.6],"p":94,"i":6,"sec":"frau-leckermauls-haus"},{"t":"h","x":"THE BOWL","sz":16.0,"box":[79.7,546.5,148.8,562.5],"p":94,"i":7,"skip":true,"sec":"the-bowl"},{"t":"ro","x":"Ein schwerer Bass-Beat begrüßt euch, als ihr durch die Eingangstür tretet. In einem großen Raum mit psychedelisch beleuchteten Sichtbetonwänden umringt eine Menschenmenge einen Tumult in ihrer Mitte. Die Clubbesucher sehen schräg aus. Wenn ihr euch durch die Menge drängt, erreicht ihr vor euch eine tieferliegende Arena aus Zement, die die Form einer riesigen konkaven Satellitenschüssel hat. In dieser „Schüssel“, die dem Fightclub seinen Namen gibt, kämpfen zwei übernatürliche Wesen gegeneinander, eines gehüllt in höllische Flammen, das andere leuchtet und hält eine Gitarre in der Hand. Adrenalin durchfährt euch, als ihr merkt: Das ist ein Ort für Leute wie euch.","sz":9.0,"box":[62.4,564.9,283.8,746.7],"p":94,"i":8,"sec":"the-bowl"},{"t":"p","x":"The Bowl ist ein Pop-Up-Untergrund-Fightclub im Industriegebiet, der nur für Risse zugänglich ist und keine Grenzen kennt. Er gehört <b>Eddie Traumzeit</b> (Mythos: die Traumzeit der Aborigines), einer der mächtigsten Legenden in der Stadt, die nicht daran interessiert ist, sie zu kontrollieren.","sz":9.5,"box":[309.0,59.9,528.0,131.9],"p":94,"i":9,"sec":"the-bowl"},{"t":"p","x":"Wenn Eddie oder Hans das Team einladen, führen sie sie zu einer rostigen Metalltür in einem verlassenen Lagerhaus, die mystisch aufleuchtet, wenn man sie öffnet. Jeder Riss, der hindurchtritt, landet in The Bowl. Den Club alleine zu finden kann schwer werden:","sz":9.5,"box":[309.0,140.6,540.6,200.1],"p":94,"i":10,"sec":"the-bowl"},{"t":"p","x":"• Zunächst muss man Kontakte im Industriegebiet konsultieren oder Hellsicht-Fähigkeiten nutzen, um herauszufinden, wo sich The Bowl am <i>betreffenden Abend</i> befindet. Meist ist das in einem verlassenen Lagerhaus, einem Silo, in einer Müllpresse usw.","sz":9.5,"box":[309.0,211.6,536.2,271.1],"p":94,"i":11,"sec":"the-bowl"},{"t":"p","x":"• Es dürfen keine Schläfer mitkommen, denn für sie funktioniert die Tür nicht.","sz":9.5,"box":[309.0,279.8,528.0,301.8],"p":94,"i":12,"sec":"the-bowl"},{"t":"p","x":"• <b>Estella</b> (Mythos: Einhorn), die muskulöse Türsteherin, stellt dem Team im Eingangsraum Fragen, ehe sie es einlässt. Jeder, der dreist genug ist, Estellas Einhorn-Reinheit mit Lügen zu beschmutzen, wird sich im Industriegebiet wiederfinden. Estella hat eine große Schlagkraft und kann gut mit ihrer Einhorn-Magie umgehen, so dass jeder, der etwas „Cleveres“ versucht, einen passenden Zustand erhält.","sz":9.5,"box":[309.0,310.4,536.6,407.4],"p":94,"i":13,"sec":"the-bowl"},{"t":"p","x":"Innen ist The Bowl ein Gewirr von nackten Betonhallen im Industrial-Stil, die sich um die Haupthalle gruppieren. Hier laufen Risse aus allen Gesellschaftsschichten umher. Einige tragen Masken, um ihre Identität zu verbergen. In der Haupthalle stehen mehrere fluoreszierende, neonbeleuchtete Bars, aber die Hauptaufmerksamkeit gilt der Arena, in der zwei Risse gegeneinander antreten. Nach dem Kampf verschwinden dank des Gastgebers alle Verletzungen, auch die tödlichen, als hätte es sie nie gegeben.","sz":9.5,"box":[309.0,413.3,538.3,535.3],"p":94,"i":14,"sec":"the-bowl"},{"t":"p","x":"Eddie Traumzeit, ein breitschultriger, mittelgroßer Mann mittleren Alters, den man meist in Outback- Kleidung und mit Körperbemalung der Aborigines sieht, beobachtet die Spiele von einem Betonbalkon.","sz":9.5,"box":[309.0,543.9,530.0,590.9],"p":94,"i":15,"sec":"the-bowl"},{"t":"sh","x":"<b>NACHFORSCHUNGEN IN DER BOWL</b>","sz":10.0,"box":[309.4,604.5,501.5,614.5],"p":94,"i":16,"sec":"the-bowl"},{"t":"p","x":"Die Risse wollen es „echt„: ob gewöhnlich oder legendär ist ihnen egal, sie wollen nur sehen, wer man ist. Wenn das Team neu ist, muss es sich im Ring beweisen, sonst zeigen ihm die meisten Risse die kalte Schulter. Eddie muss alle kennen und sie deshalb kämpfen sehen, wenn er mit ihnen reden soll. Wer noch nicht gekämpft hat, wird in die Arena eingeladen. Die SC können gegeneinander oder gegen andere Risse auf der Liste kämpfen (Eddie selbst wird nicht kämpfen). Ein Sieg ist nicht erforderlich, aber ein starker Kampfgeist hilft. Wenn die SC versuchen, auf andere Weise an Informationen zu gelangen, könnten sich die","sz":9.5,"box":[309.0,620.1,540.9,767.1],"p":94,"i":17,"sec":"the-bowl"}],"size":[595.276,841.89]},"95":{"tab":"","blocks":[{"t":"p","x":"Risse hier als widerstandsfähiger erweisen als sonst – gib ihnen eine Stärke oder einen Zustand, der ihren Fähigkeiten oder Fertigkeiten entspricht.","sz":9.5,"box":[53.9,59.9,278.3,94.4],"p":95,"i":0,"sec":"the-bowl"},{"t":"card","x":"Carter, ein verschlagener Mann im Trainingsanzug, verkauft Kandis. Er hat seine Ware von <u>Foxy Supreme</u> bekommen.","sz":null,"k":"yellow","box":[54.1,103.7,286.6,150.0],"p":95,"i":1,"sec":"the-bowl"},{"t":"card","x":"<b>Jenseits des Nebels ist Carter gerade so berührt, dass er in den Club gelangen kann.</b> Es gibt eine Spur eines griechischen Mythos (er ist von Foxy Supreme berührt), aber es ist schwer zu erkennen, welcher es genau ist.","sz":null,"k":"yellow","box":[54.1,159.3,286.6,230.7],"p":95,"i":2,"sec":"the-bowl"},{"t":"card","x":"<b>Fragt man Anwesende nach Leuten, die auf Kandis standen oder zwingt man Carter zum Reden</b>, so bekommt man die Namen von <b>DJ Hans Woods</b>, der alleinerziehenden <b>Will Harris</b> und/oder des Schwimmers <b>Juan Delamar</b>.","sz":null,"k":"yellow","box":[54.1,239.6,286.6,311.0],"p":95,"i":3,"sec":"the-bowl"},{"t":"card","x":"<b>Gerüchte über Wunscherfüllung durch Kandis gibt es genug.</b> Einige haben es probiert und können es bestätigen, während andere skeptisch sind und behaupten, es mache abhängig, man verschwände oder verlöre die Kräfte.","sz":null,"k":"yellow","box":[54.1,320.3,286.6,391.7],"p":95,"i":4,"sec":"the-bowl"},{"t":"sh","x":"<b>ÜBER HANS</b>","sz":10.0,"box":[54.3,405.8,117.3,415.8],"p":95,"i":5,"sec":"the-bowl"},{"t":"card","x":"<b>Die Clubgänger halten Hans für einen Superstar,</b> und einige beneiden ihn um seinen Erfolg. Hans war Stammgast, hat hier aber nie aufgelegt. Vor sechs Wochen wurde er entdeckt, und jetzt legt er zweimal pro Woche auf.","sz":null,"k":"yellow","box":[54.1,423.9,286.6,495.4],"p":95,"i":6,"sec":"the-bowl"},{"t":"card","x":"Hans kämpft nicht. Seine Kräfte sind nicht zum Kämpfen geeignet.","sz":null,"k":"yellow","box":[54.1,504.6,286.6,538.3],"p":95,"i":7,"sec":"the-bowl"},{"t":"card","x":"Er wohnt in einem Loft im Industriegebiet <u>(Hans‘ Loft).</u> Ein Clubgänger hat den Promi kürzlich in der Altstadt gesehen, als er seine Oma besuchte <u>(Frau Leckermauls Haus).</u>","sz":null,"k":"yellow","box":[54.1,547.5,286.6,606.5],"p":95,"i":8,"sec":"the-bowl"},{"t":"card","x":"<b>Hans ist einer der besten Kunden Carters.</b> Auch er war verschwunden, wie andere Kandis-Konsument:innen, kam aber gesund zurück. Wenn man die beiden in The Bowl beobachtet, sieht man, dass <b>Hans nicht bezahlen muss.</b> Carter kennt den Grund nicht. Seine Lieferantin, <u>Foxy Supreme,</u> will es so.","sz":null,"k":"yellow","box":[54.1,615.5,286.6,711.9],"p":95,"i":9,"sec":"the-bowl"},{"t":"card","x":"<b>Wenn das Team mit Hans redet</b>, s. seine Hinweise unter <u>Frau Leckermauls Haus.</u>","sz":null,"k":"yellow","box":[54.1,721.2,286.6,754.8],"p":95,"i":10,"sec":"the-bowl"},{"t":"sh","x":"<b>ÜBER WILL</b>","sz":10.0,"box":[309.4,62.8,370.0,72.8],"p":95,"i":11,"sec":"the-bowl"},{"t":"card","x":"<b>Will Harris ist Stammgästin.</b> Um dem Alltag zu entfliehe, kommt sie zweimal pro Woche, um in der Arena Dampf abzulassen. Sie ist eine furchterregende Kämpferin, Scharfschützin und tödlich mit der Armbrust (Wilhelm Tell).","sz":null,"k":"yellow","box":[309.3,79.2,541.7,150.6],"p":95,"i":12,"sec":"the-bowl"},{"t":"card","x":"Gestern Abend ist sie nicht erschienen, was ungewöhnlich ist.","sz":null,"k":"yellow","box":[309.3,159.8,541.7,193.5],"p":95,"i":13,"sec":"the-bowl"},{"t":"card","x":"Sie lebt in einer kleinen Wohnung mit ihrem 6-jährigen Sohn <u>(Will Harris‘ Apartment)</u> und hatte finanzielle Probleme, aber vor kurzem kam sie unverhofft zu etwas Geld.","sz":null,"k":"yellow","box":[309.3,202.8,541.7,261.5],"p":95,"i":14,"sec":"the-bowl"},{"t":"sh","x":"<b>ÜBER JUAN</b>","sz":10.0,"box":[309.4,276.8,370.0,286.8],"p":95,"i":15,"sec":"the-bowl"},{"t":"card","x":"<b>Juan Delamar</b> ist Goldmedaillengewinner im Schwimmen, und gelegentlich in The Bowl. Er trägt stets eine Maske, damit ihn niemand erkennt, aber trotzdem sind ständig Fans dabei, die ihn anstarren und tuscheln. Juan trainiert im <u>öffentlichen Schwimmbad.</u>","sz":null,"k":"yellow","box":[309.3,303.0,541.7,386.8],"p":95,"i":16,"sec":"the-bowl"},{"t":"card","x":"<b>Seine Kräfte sind aquatisch.</b> Er kämpfte in der mit Wasser gefüllten Arena gegen andere Risse, deren Kräfte mit Wasser zu tun haben. Juan ist sehr wettbewerbsorientiert und ehrgeizig.","sz":null,"k":"yellow","box":[309.3,396.0,541.7,454.8],"p":95,"i":17,"sec":"the-bowl"},{"t":"card","x":"<b>Er war seit Wochen nicht mehr da.</b> Es heißt, er habe seine Kräfte aufgegeben, um herauszufinden, wie gut er wirklich ist oder um mehr Glück bei Mädchen zu haben, weil er dachte, seine Legende mache ihn hässlich.","sz":null,"k":"yellow","box":[309.3,464.0,541.7,535.1],"p":95,"i":18,"sec":"the-bowl"},{"t":"p","x":"<b>Ein Querverweis auf Details über Juan könnte helfen, seinen Mythos als den Ningyo</b> zu identifizieren, ein Meereswesen der japanischen Mythologie, das an eine abscheuliche Meerjungfrau erinnert. Der Mythos besagt, <b>der Verzehr des Fleisches des Ningyo verleihe ewiges Leben</b>, ein wichtiges Detail der mystischen Ebene: Juans Ichor wird zum Dreh- und Angelpunkt bei Armands Suche nach dem Lebenselixier.","sz":10.0,"box":[317.5,550.0,531.6,672.5],"p":95,"i":19,"sec":"the-bowl"}],"size":[595.276,841.89]},"96":{"tab":"","blocks":[{"t":"sh","x":"<b>KÄMPFEN IN DER BOWL</b>","sz":10.0,"box":[54.3,62.8,185.2,72.8],"p":96,"i":0,"sec":"the-bowl"},{"t":"p","x":"Sobald Teammitglieder die wundersame Wiederherstellung besiegter Kämpfer:innen mitbekommen und erkennen, dass die Teilnahme an den Kämpfen ungefährlich ist (auch wenns wehtut), möchten sie vielleicht ihren Hut in den Ring werfen. Sie können gegen Risse im Club, einen in der Serie bereits eingeführten Charakter oder gegeneinander antreten.","sz":9.5,"box":[53.9,78.3,281.9,162.8],"p":96,"i":1,"sec":"the-bowl"},{"t":"p","x":"Die Arena ist eine nackte Betongrube, in der die Kämpfe stattfinden. Sie hat keine besonderen Eigenschaften, außer, dass sie je nach Bedarf an die Kämpfenden angepasst werden kann, z. B. kann man für fliegende Risse den Boden wegklappen oder sie für aquatische Risse mit Wasser füllen.","sz":9.5,"box":[53.9,171.5,286.0,243.5],"p":96,"i":2,"sec":"the-bowl"},{"t":"p","x":"Wenn Kämpfer:innen um die Gunst des Publikums werben, gib dem ein <i>Für sich gewinnen 5</i>-Spektrum.","sz":9.5,"box":[53.9,252.2,268.4,274.2],"p":96,"i":3,"sec":"the-bowl"},{"t":"h","x":"EDDIE TRAUMZEIT, DER INHABER","sz":14.0,"box":[65.2,299.1,217.4,313.1],"p":96,"i":4,"sec":"the-bowl"},{"t":"p","x":"Der Inhaber des Fightclubs wacht gewöhnlich von einem Betonbalkon im VIP-Bereich über die Arena. Er weiß viel über die Vorgänge in der Stadt und ihre Risse, hält sich aber aus den Machtspielchen der Torwächter und Avatare heraus und mischt sich nicht ein. Trotzdem liebt er seine Mit-Risse und ist besorgt über die neue Droge, vor allem, weil sie ihnen ihre Kräfte zu nehmen scheint. Er ist bereit, jemanden zu helfen, der das Problem lösen kann.","sz":9.0,"box":[65.2,325.6,267.5,430.6],"p":96,"i":5,"sec":"the-bowl"},{"t":"p","x":"Eddie Traumzeit glaubt an die Freiheit, so zu sein, wie man ist. Er hat den Club als Ort geschaffen, an dem Risse ihre Hemmungen und Ängste an der Tür abgeben und Kräfte einsetzen können, ohne sich zurückzuhalten. Es geht um mehr als Kampf. In der Bowl finden musikalische und magische Turniere statt, und wer die Hinterzimmer erkundet, findet leere Bereiche, wo man jede Kraft ausprobieren kann. Der gesamte Club, einschließlich der Besuchenden, ist von Eddie beschworen. Wird jemand in der Arena getötet, stirbt lediglich sein Abbild. Die wirklichen Kämpfer sind sicher in der physischen Welt, und niemand bekommt etwas davon mit.","sz":9.0,"box":[65.2,439.3,271.9,592.3],"p":96,"i":6,"sec":"the-bowl"},{"t":"p","x":"Eddie ist der mächtigste Wirklichkeitsformer der Stadt, obwohl er bei zwei Gelegenheiten in der Arena unterlegen ist. Er hat keine Werte, weil er normalerweise keine Bedrohung für die Ermittlungen oder das Team (das ihm nicht gewachsen ist) darstellt. Benimmt sich jemand daneben, finden der sich blitzschnell im Industriegebiet (oder schlimmer) wieder. Eddie ist gut vernetzt und kann das Team in Schwierigkeiten bringen oder unterstützen, obwohl er durch seine selbst auferlegte Neutralität eingeschränkt ist.","sz":9.0,"box":[65.2,601.0,273.9,718.0],"p":96,"i":7,"sec":"the-bowl"},{"t":"p","x":"Kandis funktioniert im Bowl nur, wenn Eddie es zulässt. Normalerweise schränkt er die Kräfte von Rissen nur ungern ein, aber wenn jemand es mit den Wünschen übertreibt, gehen sie nach hinten los.","sz":9.0,"box":[65.2,726.6,272.7,771.6],"p":96,"i":8,"sec":"the-bowl"},{"t":"p","x":"Beide Kämpfer:innen verleihen dem Publikum darauf jeweils eigene Zustände. Wer als erster das Maximum des Spektrums erreicht, gewinnt das Publikum für sich. Ein musikalisches Duell entscheidet man, indem man die Menge gewinnt. In einem Zweikampf hat die Gunst des Publikums keinen Effekt auf den Sieg, kann sich aber darauf auswirken, wie die Risse die Kämpfer:innen danach sehen. (Wenn der Gegner Apollo ist, aktiviert er seine Aktion <b>Baut mir einen Schrein</b>, wenn er das Publikum auf seiner Seite hat).","sz":9.5,"box":[309.0,59.9,541.0,181.9],"p":96,"i":9,"sec":"the-bowl"},{"t":"p","x":"<b>Crescendo:</b> Das Publikum konzentriert sich auf die Person, die es <i>Für sich gewonnen</i> hat, und schreit nach einem musikalischen Höhepunkt: einem Solo, einem unmöglichen Riff oder einem gesanglichen Crescendo. Man kann <b>Ein Risiko einzugehen</b>, um dem Publikum den Wunsch zu erfüllen. Bei Erfolg steigt die Stufe des verliehenen Zustands um 1.","sz":9.5,"box":[309.0,190.6,539.0,275.1],"p":96,"i":10,"sec":"the-bowl"},{"t":"threat","stars":"★★★","name":"APOLLO","spectra":"","items":[],"box":[358.3,309.7,388.9,321.7],"p":96,"i":11,"sec":"the-bowl"},{"t":"p","x":"Apollo (der griechische Sonnengott) ist perfekt und nervig. Er ist ein schlanker Gitarrist im 80er-Jahre-Outfit – grelle Farben, Schulterpolster, das ganze Drum und Dran – mit einer schicken Frisur und Umhänge-Keyboard über der Schulter. Wenn er seine Kräfte nutzt, blinken um ihn herum bunte Lichter wie Discokugeln. Apollo nimmt an physischen wie musikalischen Wettkämpfen teil. Er liebt Aufmerksamkeit und flirtet während eines Kampfes mit der Menge.","sz":9.0,"box":[317.5,332.9,531.7,437.9],"p":96,"i":12,"sec":"the-bowl"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 3</b>","sz":12.0,"box":[317.5,448.4,496.7,460.4],"p":96,"i":13,"sec":"the-bowl"},{"t":"p","x":"• <b>Spektakulärer Auftritt</b>: Wenn Apollo die Szene betritt, verleihe ihm <t>Glanz und Glitter 2</t>. • <b>Olympisch</b>: Zustände durch körperlichen Schaden oder Suggestion oder wenn er durch körperlichem Schaden unschädlich gemacht werden würde, reduziere die Stufe um 2 (legendär) oder um 3 (weltlich). • <b>Synthwave</b>: Wenn man im Nahkampf angreift, wirst man durch blendende Lichter <t>verwirrt 2</t>. Erhält Apollo durch einen Energiestoß einen Zustand, begegnet er dem Stoß mit einer Schallwelle aus der Gitarre, die dessen Stufe um 3 senkt. • <b>Baut mir einen Schrein</b>: Wenn Apollo ein Publikum <i>Für sich gewinnt,</i> erhält er <t>unter Strom 3</t>.","sz":9.0,"box":[317.5,464.9,533.3,617.9],"p":96,"i":14,"sec":"the-bowl"},{"t":"p","x":"• Jemanden mit einer Gitarren-Schallwelle treffen und durch die Arena schleudern (<t>desorientiert 3</t>) • Das Publikum mit Synthesizer-Musik begeistern","sz":9.0,"box":[317.5,626.9,519.3,659.9],"p":96,"i":15,"sec":"the-bowl"},{"t":"sh","x":"(<t>WOW 4</t>)","sz":9.0,"box":[326.0,662.9,361.7,671.9],"p":96,"i":16,"sec":"the-bowl"},{"t":"p","x":"• Ein Comeback machen (bei sich, den Gegner:innen oder Publikum bis zu zwei Stufen eines sozialen oder musikalischen Zustands entfernen)","sz":9.0,"box":[317.5,674.9,528.8,707.9],"p":96,"i":17,"sec":"the-bowl"},{"t":"p","x":"• Mit wehendem Haar ein kompliziertes, beglückendes elektronisches Riff spielen • Dem Publikum mit unwiderstehlichem Lächeln zuwinken","sz":9.0,"box":[317.5,716.9,527.5,761.9],"p":96,"i":18,"sec":"the-bowl"}],"size":[595.276,841.89]},"97":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"NELLIE","spectra":"","items":[],"box":[98.6,57.5,129.2,69.5],"p":97,"i":0,"sec":"the-bowl"},{"t":"p","x":"Nellie (Nisse, nordischer Hausgeist) ist eine kleinwüchsige junge Frau und wie ein Landei gekleidet: Jeans, Stiefel und knallroter Hoodie mit spitz zulaufender Kapuze. Sie stammt dem Dorf und ist in die Stadt gezogen, um als Haushaltshilfe und Kindermädchen zu arbeiten. Als Ordnungsfanatikerin und Anhängerin alter ländlicher Werte findet sie ihre Arbeitgeber:innen und deren Kinder unhöflich, undiszipliniert und höchst ärgerlich, weshalb sie in The Bowl kommt, um Dampf abzulassen, indem sie Leute verprügelt. Nellies Mythos verleiht ihr immense Kräfte, die Fähigkeit, sich unsichtbar zu machen, und eine Vorliebe dafür, ihren Gegner:innen Streiche zu spielen.","sz":9.0,"box":[62.4,80.6,275.7,245.6],"p":97,"i":1,"sec":"the-bowl"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4</b>","sz":12.0,"box":[62.4,256.1,241.3,268.1],"p":97,"i":2,"sec":"the-bowl"},{"t":"p","x":"• <b>Findet mich, wenn ihr könnt</b>: Wenn Nellie zum ersten Mal in einer Szene unsichtbar wird, gib jedem <t>kann Nellie nicht sehen 5</t> (SC können <b>Sich der Gefahr stellen</b>). Wer in einem Kampf nach Nellie sucht, muss <b>Nachforschungen</b> anstellen. Jeder Hinweis kann den Zustand um 1 Stufe verringern. Bei einer 7-9 bei Sich der Gefahr stellen schlägt sie den betreffenden SC (s. u., Harte Aktionen).","sz":9.0,"box":[62.4,272.6,272.9,365.6],"p":97,"i":3,"sec":"the-bowl"},{"t":"p","x":"• <b>Wütender Wichtel</b>: Wenn Nellie die Szene betritt, gib ihr <i>Dickkopf</i> und <i>Temperament</i>.","sz":9.0,"box":[317.5,82.9,529.7,103.9],"p":97,"i":4,"sec":"the-bowl"},{"t":"p","x":"• Jemanden mit Wucht verprügeln und ordentliches Benehmen und Respekt predigen (<t>Knochenbrüche 4</t> oder <t>fast ohnmächtig 4</t>. Wenn sie unsichtbar ist, sinkt die Stufe des Zustands <t>kann Nellie nicht sehen</t> um 1 für das Ziel und jeden, der aufmerksam ist) • Einen Gegenstand stehlen, den jemand in der Hand hält (ggf. eine Stärke verbrennen und den Zustand <t>kann Nellie nicht sehen</t> wie oben verringern) • Jemanden zum Zwerg machen (<t>geschrumpft 3</t>) • Von verschiedenen Orten aus sprechen, um zu verwirren (<t>kann Nellie nicht sehen 5</t> erneuern)","sz":9.0,"box":[317.5,112.9,530.8,241.9],"p":97,"i":5,"sec":"the-bowl"},{"t":"p","x":"• Über die Unhöflichkeit von Gegner:innen schimpfen und sie tadeln, dabei aber offenbar über jemand anderen sprechen • Sich in Luft auflösen","sz":9.0,"box":[317.5,250.9,531.6,295.9],"p":97,"i":6,"sec":"the-bowl"}],"size":[595.276,841.89]},"98":{"tab":"","blocks":[{"t":"h","x":"WILL HARRIS‘ WOHNUNG","sz":16.0,"box":[79.7,68.9,245.8,84.9],"p":98,"i":0,"skip":true,"sec":"will-harris-wohnung"},{"t":"ro","x":"Es ist ein ganz normaler Tag, als ihr die Adresse erreicht, die ihr von Will Harris habt. Zwei Reihen von Wohnhäusern mit kleinen Läden im Erdgeschoss säumen die Straße. Alles ist voller Menschen, die Besorgungen machen und ihrem Alltag nachgehen. Neben einer Gruppe von Ganov:innen führt die kaum beleuchtete Treppe nach oben. Eine neugierige Frau, vielleicht die Vermieterin, späht durch einen Türspalt. Ihr macht euch eine geistige Notiz: Das kommt euch sehr normal vor.","sz":9.0,"box":[62.4,87.3,283.8,215.1],"p":98,"i":1,"sec":"will-harris-wohnung"},{"t":"p","x":"Die Szene in Will Harris‘ einfacher Ein-Zimmer-Wohnung kann sich auf zwei Arten abspielen:","sz":9.5,"box":[53.9,224.1,278.5,246.1],"p":98,"i":2,"sec":"will-harris-wohnung"},{"t":"p","x":"• Will Harris wird möglicherweise vermisst, in diesem Fall passt ihre 20 Jahre alte Schwester <b>Beth</b> auf Wills Sohn <b>Albert</b> (beides Schläfer) auf. Sie sind verzweifelt und scheinen ohne Will nicht klarzukommen.","sz":9.5,"box":[53.9,257.6,284.8,304.6],"p":98,"i":3,"sec":"will-harris-wohnung"},{"t":"p","x":"• Will könnte gerade nach Hause zurückgekehrt sein, nachdem sie durch den Ofen ihre Kräfte verloren hat. Sie ist eine große, wendige Frau Mitte dreißig mit einem flippigen Bürstenschnitt und lässigen Jeans und T-Shirt. Sie wirkt erschöpft und distanziert.","sz":9.5,"box":[53.9,313.2,286.7,372.7],"p":98,"i":4,"sec":"will-harris-wohnung"},{"t":"p","x":"Dies ist ein Schauplatz für Nachforschungen. Die NSC hier sind friedliche Schläfer:innen und werden wahrscheinlich keinen Ärger machen, es sei denn, die SC bedrängen sie, dann rufen sie vielleicht die Polizei.","sz":9.5,"box":[53.9,378.6,280.5,425.6],"p":98,"i":5,"sec":"will-harris-wohnung"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER WILLS VERSCHWINDEN</b>","sz":10.0,"box":[54.3,439.2,202.1,461.2],"p":98,"i":6,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Will Harris ist (oder war) seit einem Tag verschwunden.</b> Zuletzt hat man sie gestern morgen gesehen, als sie Albert in den Kindergarten brachte. Sie kam nicht zum Abholen, was noch nie vorgekommen ist. Der Kindergarten rief Beth als Notfallkontakt an. Später fand Beth heraus, dass Will nicht auf der Arbeit war (sie arbeitet als Grafikdesignerin für eine gemeinnützige Organisation).","sz":null,"k":"yellow","box":[54.1,468.6,286.6,590.1],"p":98,"i":7,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Will hatte finanzielle Schwierigkeiten und vor kurzem einen Geldsegen,</b> der ermöglichte, alle ihre Rechnungen zu bezahlen. Das kann man herausfinden, indem man sich mit Beth unterhält, Wills Kontoauszüge unter die Lupe nimmt, in der Mülltonne stöbert oder mit der Vermieterin im Erdgeschoss plaudert.","sz":null,"k":"yellow","box":[54.1,599.3,286.6,695.5],"p":98,"i":8,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Das Geld scheint aus dem Nichts gekommen zu sein</b> – sie könnte es als Bargeld eingezahlt haben, oder es ist ohne Absenderangabe auf ihrem Konto eingegangen.","sz":null,"k":"yellow","box":[54.1,704.7,286.6,763.5],"p":98,"i":9,"sec":"will-harris-wohnung"},{"t":"card","x":"Sowohl Beth als auch Albert wissen, dass <b>Will ein geheimes Leben führte</b>: Sie hat nicht offen über ihre nächtlichen Ausgänge zweimal pro Woche gesprochen. Beth ist ihr einmal zu einem Rave im Industriegebiet gefolgt, dort aber an der Türsteherin gescheitert <u>(The Bowl).</u> Sie befürchtet, dass dies etwas mit dem Geldsegen und ihrem Verschwinden zu tun hat.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,163.0],"p":98,"i":10,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Hinter dem Schrank</b> hat jemand ein Loch in die Wand gemeißelt und Gegenstände versteckt: drei Armbrüste aus verschiedenen Epochen und mehrere leere Bonbonverpackungen.","sz":null,"k":"yellow","box":[309.3,172.2,541.7,231.0],"p":98,"i":11,"sec":"will-harris-wohnung"},{"t":"card","x":"Albert hat Angst, er könne am Verschwinden schuld sein. Ein Junge aus der Schule, <b>Charlie, habe ihn dazu gebracht, vor ein paar Tagen Süßigkeiten aus der Jackentasche seiner Mutter zu stehlen</b>. Albert berichtet, dass Charlie ein gigantisches Zimmer hat, größer als dieses gesamte Gebäude <u>(Charlies Spielzimmer).</u>","sz":null,"k":"yellow","box":[309.3,240.2,541.7,336.4],"p":98,"i":12,"sec":"will-harris-wohnung"},{"t":"card","x":"Will hat das Kandis von Carter <u>(The Bowl)</u> .","sz":null,"k":"yellow","box":[309.3,345.6,541.7,366.9],"p":98,"i":13,"sec":"will-harris-wohnung"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER WILLS RÜCKKEHR</b>","sz":10.0,"box":[309.4,380.2,457.2,402.2],"p":98,"i":14,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Will verhält sich normal, wirkt aber müde und abwesend.</b> Sowohl Beth als auch Albert sind über ihr Verhalten beunruhigt. Ihnen zufolge <b>war Will immer heiter und witzig</b>.","sz":null,"k":"yellow","box":[309.3,409.2,541.7,468.0],"p":98,"i":15,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Will ist eine Schläferin. Das macht jedes Gespräch mit ihr klar, und das ergibt auch ein Blick hinter den Nebel.</b> Sie kann sich nicht entsinnen, ein Riss gewesen zu sein, und erinnert sich nur vage an Raves im Industriegebiet und Drogen – eine schwierige Zeit, die sie nun unbedingt hinter sich lassen will.","sz":null,"k":"yellow","box":[309.3,477.2,541.7,573.4],"p":98,"i":16,"sec":"will-harris-wohnung"},{"t":"card","x":"<b>Weiter jenseits des Nebels</b> trägt Will Spuren des Ofens (s. S. Die Ofenspur, S. 93).","sz":null,"k":"yellow","box":[309.3,582.6,541.7,616.6],"p":98,"i":17,"sec":"will-harris-wohnung"}],"size":[595.276,841.89]},"99":{"tab":"","blocks":[{"t":"h","x":"DAS SCHWIMMBAD","sz":16.0,"box":[79.7,68.9,209.8,84.9],"p":99,"i":0,"skip":true,"sec":"das-schwimmbad"},{"t":"ro","x":"Das Licht, das sich im Wasser spiegelt, wirft seltsame blaue Silhouetten an die Decke der Schwimmhalle. In den fließenden Umrissen kann man Sirenen, Seeungeheuer und Meerjungfrauen erkennen. Eine laute Besucher:innenschar räumt das olympische Becken, um Platz für das Training des Schwimmteams zu machen, und hinterlässt den Ort wie ausgestorben. Da seht ihr den muskulösen Mann mittleren Alters mit roter Mütze, den Trainer. Eure Blicke treffen sich. Seiner ist grimmig und besorgt.","sz":9.0,"box":[62.4,87.3,283.8,215.1],"p":99,"i":1,"sec":"das-schwimmbad"},{"t":"p","x":"Das Schwimmbad ist der Schauplatz, an dem das Team den Fall Juan Delamars untersuchen kann, des bekannten Goldmedaillenschwimmers, der sein Talent verlor.","sz":9.5,"box":[53.9,224.1,285.9,258.6],"p":99,"i":2,"sec":"das-schwimmbad"},{"t":"p","x":"Ansprechpartner ist <b>Trainer Bradley Ferrell</b> (Schläfer), Juans Schwimmtrainer, der sich Sorgen über die schwachen Leistungen macht. Der Trainer würde Juan gerne professionelle Hilfe besorgen, aber er hat <t>Angst vor schlechter Publicity 1</t>. Wenn sich das Team ohne Einladung oder Referenzen (Polizei, Privatdetektiv, Berater usw.) an ihn wendet, erhöhe den Zustand auf 3.","sz":9.5,"box":[53.9,267.2,283.1,364.2],"p":99,"i":3,"sec":"das-schwimmbad"},{"t":"p","x":"Nach dem Training kann man in der Umkleide mit <b>Juans Mannschaftskameraden</b> plaudern. Sie wissen mehr über Juans persönliches (und geheimes) Leben, aber sie <t>beschützen ihren Champion 2</t>, wobei man mit gesellschaftlichen <b>Nachforschungen</b> einen gesprächigeren Kameraden herauspicken könnte, um den Zustand zu umgehen, vielleicht jemand, der eifersüchtig auf Juans Erfolg ist oder sich Sorgen macht.","sz":9.5,"box":[53.9,372.9,285.2,469.9],"p":99,"i":4,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Juan war schon immer ein hervorragender Schwimmer</b> (was den Zusammenhang zwischen Schwimmen und Kandis ausschließt).","sz":null,"k":"yellow","box":[54.1,480.1,286.6,526.5],"p":99,"i":5,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Seit dem „wilden Wochenende“, an dem er nicht nach Hause kam, brach seine Leistung ein:</b> Er schien jegliches Talent verloren zu haben. Wo er früher anmutig durchs Wasser glitt, wirkte er jetzt unbeholfen, mit guter Technik, aber ohne seine frühere Kraft und Kompetenz.","sz":null,"k":"yellow","box":[54.1,535.7,286.6,619.5],"p":99,"i":6,"sec":"das-schwimmbad"},{"t":"card","x":"Der Trainer bemühte sich sehr, die Information vor der Mannschaftsführung geheim zu halten, da er befürchtete, Juan könnte aus dem Team fliegen. Er ist sehr darauf bedacht, Juan wieder in die Mannschaft zu integrieren.","sz":null,"k":"yellow","box":[54.1,628.4,286.6,699.8],"p":99,"i":7,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Einer seiner Teamkollegen</b> weiß, dass Juan seit seinem siebzehnten Lebensjahr in einen Club im Industriegebiet geht <u>(The Bowl).</u> Er hat auch eine leere Bonbonverpackung aufbewahrt, die Juan einmal fallen gelassen hat.","sz":null,"k":"yellow","box":[54.1,709.1,286.6,780.5],"p":99,"i":8,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Juan nahm Kandis, um Liebe zu finden.</b> Aufgrund seines unscheinbaren Äußeren und seiner Unsicherheit hatte er Schwierigkeiten, eine Partnerin zu finden. Vor ein paar Wochen begann er eine Beziehung mit einem Mädchen aus seinem College, aber sie verließ ihn nach dem schicksalhaften Wochenende.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,150.6],"p":99,"i":9,"sec":"das-schwimmbad"},{"t":"card","x":"Juan hat das Kandis von Carter <u>(The Bowl).</u>","sz":null,"k":"yellow","box":[309.3,159.6,541.7,180.9],"p":99,"i":10,"sec":"das-schwimmbad"},{"t":"p","x":"Irgendwann kommt Juan persönlich zum Training (oder das Team findet ihn bei seiner Familie zu Hause). Er ist ein schlanker, dunkelhaariger junger Mann von unterdurchschnittlicher Größe, etwa zwanzig Jahre alt, und hat eine Sporttasche mit Schwimmzeug dabei. Er ist ruhig, gelassen und introvertiert.","sz":9.5,"box":[309.0,191.7,540.8,263.7],"p":99,"i":11,"sec":"das-schwimmbad"},{"t":"card","x":"Während des Trainings bewegt Juan sich völlig mechanisch. Die anderen Schwimmer und Trainer Farrell starren ihn an und tuscheln, aber Juan zeigt keine Reaktion, nicht einmal ein Achselzucken oder zusammengebissene Zähne. <b>Er wirkt wie betäubt.</b>","sz":null,"k":"yellow","box":[309.3,272.4,541.7,356.3],"p":99,"i":12,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Juan erinnert sich nicht an Details seiner Kandis-Sucht und des Partywochenendes.</b> Alles, was man ihm beim Aufwachen gesagt hat, ist, dass er mit falschen Drogen experimentiert, einen schlechten Trip hatte und dass es ihn seine Karriere kosten könne. Die Leute um ihn beschimpfen ihn, weil er sein Talent verschleudert, aber das ist ihm egal. <b>Er überlegt ernsthaft, mit dem Schwimmen aufzuhören.</b>","sz":null,"k":"yellow","box":[309.3,365.5,541.7,486.7],"p":99,"i":13,"sec":"das-schwimmbad"},{"t":"card","x":"Juan sieht immer noch schlicht aus, <b>aber ihm fehlen einige der Gesichtszüge seines Mythos, die auf einem früheren Mannschaftsfoto zu sehen waren:</b> Stupsnase, knöcherne Auswüchse und hervortretende Augen.","sz":null,"k":"yellow","box":[309.3,495.9,541.7,567.4],"p":99,"i":14,"sec":"das-schwimmbad"},{"t":"card","x":"<b>Jenseits des Nebels</b> ist Juan ein Schläfer. <b>Weiter jenseits des Nebels</b> trägt er Spuren des Ofenmythos (s. S. Die Ofenspur, S. 93).","sz":null,"k":"yellow","box":[309.3,576.3,541.7,622.7],"p":99,"i":15,"sec":"das-schwimmbad"}],"size":[595.276,841.89]},"100":{"tab":"","blocks":[{"t":"h","x":"CHARLIES SPIELZIMMER","sz":16.0,"box":[79.7,68.9,243.4,84.9],"p":100,"i":0,"skip":true,"sec":"charlies-spielzimmer"},{"t":"ro","x":"Irgendetwas schiebt und dreht sich, wenn man sich Charlies Zimmerecke nähert. Ihr seid nicht sicher, ob es die Wände, der Raum oder euer Verstand ist. Jenseits des Gefühls ragen rote Backsteinwände Dutzende von Metern in die Höhe und erstrecken sich weit in die Dunkelheit. Riesige Spielzeugstapel – Actionfiguren, Modellautos, Klemmbausteine aller Art – bilden ein topografisches Terrain, das sich auf einem großflächigen Teppich ausbreitet. Dazwischen sitzt ein kleiner Junge und spielt, bis er euch bemerkt und ruft: „Habt ihr Süßigkeiten? Ich will mehr!„","sz":9.0,"box":[62.4,87.3,283.8,236.7],"p":100,"i":1,"sec":"charlies-spielzimmer"},{"t":"p","x":"Charlie Littles ist ein kindlicher Riss und Tyrann, der dank des Voodoopuppen-Mythos Menschen und Gegenstände manipulieren kann, indem er kleine Abbilder von ihnen bewegt. Charlie stahl mit Hilfe von Albert (der dieselbe Schule wie Charlie besucht) Will Harris‘ Kandis und entdeckte, dass es Wünsche erfüllen kann. Also wünschte er sich jede Menge Spielzeug und ein Zimmer, das groß genug dafür ist. In der letzten Woche hat er sich stundenlang in seinem magischen Raum vergnügt, aber jetzt, da Sachen langsam verschwinden und das Zimmer auf seine ursprüngliche Form (eine Ecke im kleinen Kinderzimmer) schrumpft, sehnt sich Charlie verzweifelt nach mehr Kandis.","sz":9.5,"box":[53.9,245.7,286.3,405.2],"p":100,"i":2,"sec":"charlies-spielzimmer"},{"t":"p","x":"Das Team kann hierher finden, wenn es Gerüchte über Wunscherfüllung hört, das Kandis hierher zurückverfolgt oder durch Hinweise von Will Harris‘ Sohn Albert. Die Action könnte Abwechslung in der Ermittlung sein und das Team gleichzeitig mit Hinweisen belohnen.","sz":9.5,"box":[53.9,413.8,286.6,473.3],"p":100,"i":3,"sec":"charlies-spielzimmer"},{"t":"p","x":"Die Littles sind eine vierköpfige Familie, die in einer bescheidenen Drei-Zimmer-Wohnung nicht weit von Will und Albert Harris lebt. Alle anderen Familienmitglieder sind Schläfer:innen und haben keine Ahnung, dass sich Charlies Spielzeugecke in ein gigantisches Zimmer verwandelt hat: Sie können sich nicht erinnern, wie geräumig die Ecke war oder wann sie all die Spielsachen gekauft haben. Für Risse ist der Raum so groß wie eine weitläufige Hotellobby, man gelangt über die Ecke von Charlies Zimmer hinein. In der Mitte sitzt inmitten von Spielzeugbergen Charlie, ein sommersprossiger, pummeliger Junge mit braunem Haar.","sz":9.5,"box":[53.9,482.0,285.4,629.0],"p":100,"i":4,"sec":"charlies-spielzimmer"},{"t":"sh","x":"<b>CHARLIES PLAN</b>","sz":10.0,"box":[54.3,639.8,142.5,649.8],"p":100,"i":5,"sec":"charlies-spielzimmer"},{"t":"p","x":"Weil er sich nach mehr Kandis sehnte, folgte Charlie den psychedelischen Kieseln in die Fabrik. Doch er hatte zu viel Angst, um sie zu betreten. Charlie sucht Risse als Leibwache, die ihn zum Ofen begleiten sollen. Wenn er merkt, dass Risse sein Spielzimmer betreten, sucht sich Charlie die Stärksten aus und versucht, die Kontrolle über sie zu übernehmen. Charlie ist grausam, wie es nur Kinder sein können. Er wird damit drohen, einen SC zu verletzen, wenn ein anderer nicht tut, was","sz":9.5,"box":[53.9,655.3,286.4,764.8],"p":100,"i":6,"sec":"charlies-spielzimmer"},{"t":"p","x":"er sagt, oder einen SC benutzen, um einen anderen zu verletzen. Kontrollierte Risse führt er in die alte <u>Aurora-Glashütte,</u> wo sie als Wache dienen und Kandis besorgen sollen. <b>Beachte, dass Charlie so dem Team erlaubt, die zweite Schicht zu überspringen.</b>","sz":9.5,"box":[309.0,59.9,539.6,119.6],"p":100,"i":7,"sec":"charlies-spielzimmer"},{"t":"threat","stars":"★★★","name":"CHARLIE","spectra":"UNTERWERFEN 1 / ANFREUNDEN 4 / BEDROHEN 4","items":["<b>Leibwächter</b>: Wenn Charlie einen Zustand nimmt, vor dem ihn die Leibwache schützen kann, nimmt diese ihn (nutze Riesen-Voodoo-Spielzeuge).","<b>Tyrann</b>: Ein Anfreunden-Zustand sinkt um 2, es sei denn, man tut etwas Cooles oder ist gemein zu jemandem. Bei Bedrohung sinkt die Stufe um 1.","<b>Wutanfall</b>: Wenn jemand eines von Charlies Spielzeugen besiegt, verliert er alle Zustandswerte auf seinen <i>Anfreunden</i>- und <i>Bedrohungs</i>-Spektren.","Mit Spielzeug herumspielen und so eine riesige Version desselben Spielzeugs beleben (Neue Bedrohung: Riesen-Voodoo-Spielzeuge. Charlie kann nur ein Spielzeug pro Hand kontrollieren und muss es weglegen, um ein weiteres zu wecken. Ein weggelegtes Spielzeug kann keine Bedrohung machen).","Mit Spielzeug, das wie jemand oder etwas aussieht, kann er die Person/den Gegenstand manipulieren (<t>kontrolliert 3</t>) oder verletzen (<t>stechender Schmerz 3</t>)","Den Stapel oder seine Taschen nach einem Spielzeug durchsuchen, das aussieht wie jemand","Sich Kandis in den Mund stopfen und Spielzeug wünschen, das wie das Team aussieht (damit er es kontrollieren kann)","Gehässig kichern, wenn das Spielzeug auf jemanden einschlägt"],"box":[362.9,144.7,393.5,156.7],"p":100,"i":8,"sec":"charlies-spielzimmer"},{"t":"threat","stars":"★★★","name":"RIESEN-VOODOO-SPIELZEUGE","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 5","items":["<b>Ungeheuerlich</b>: Wenn es einen Zustand erhält, dem seine Größe entgegenwirkt, sinkt die Stufe um 1. Wenn die SL mit ihm eine harte Aktion ausführt, kann es zwei Ziele oder eines für +1 Stufe treffen.","Jemanden umarmen (<t>festgehalten 3</t>) oder einen kräftigen Schlag verpassen (<t>desorientiert 3</t>)","Eine Funktion des Spielzeugs aktivieren, z. B. Abfeuern von Laserstrahlen, Fliegen, Werfen einer Blendgranate usw. (als harte Aktion)","Unbeholfen fuchtelnd auf das Ziel zubewegen"],"box":[465.7,559.3,496.3,571.3],"p":100,"i":9,"sec":"charlies-spielzimmer"}],"size":[595.276,841.89]},"101":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[53.9,69.1,122.1,83.1],"p":101,"i":0,"skip":true,"sec":"schicht-2-suche-nach-brotkrumen"},{"t":"h","x":"SUCHE NACH BROTKRUMEN","sz":23.0,"box":[53.9,91.4,191.6,142.4],"p":101,"i":1,"skip":true},{"t":"h","x":"FOXY SUPREME","sz":16.0,"box":[79.7,156.0,183.7,172.0],"p":101,"i":2,"skip":true,"sec":"foxy-supreme"},{"t":"ro","x":"Die im Neonlicht blau schimmernde Foxy Supreme schmiegt sich in einen üppigen weißen Pelzmantel und ein funkelndes, diamantenbesetztes Minikleid. Die Art, wie sie sich bewegt und einen hochhackigen Schritt sanft vor den anderen setzt, lässt vermuten, dass sie ihren Spitznamen zu Recht trägt. Ihre Augen, die von blonden Locken umrahmt sind, verfolgen eure Blicke. Wenn jemand das alles überlebt, dann sie.","sz":9.0,"box":[62.4,174.4,283.8,291.4],"p":101,"i":3,"sec":"foxy-supreme"},{"t":"p","x":"Foxy Supreme ist eine gefährliche, nihilistische, umwerfend gut aussehende Dealerin und ein altgedienter Riss. Sie arbeitete für die ursprüngliche Lebkuchenhexe, Rosina Leckermaul, und wechselte zu Rachel Woods, als diese ihre alte Chefin in den Ofen schob. Im letzten Monat hat sie für ihre neue Chefin mehr Kandis als je zuvor unter die Leute gebracht und damit ein kleines Vermögen verdient. Sie weiß, dass solche Gier zwangsläufig nach hinten losgeht, aber das ist ihr egal, dank ihres Mythos und Einfallsreichtums kann sie niemand erwischen – zumindest glaubt sie das.","sz":9.5,"box":[53.9,300.4,286.2,434.9],"p":101,"i":4,"sec":"foxy-supreme"},{"t":"p","x":"<b>Die hochkarätige Kriminelle zu finden ist nicht leicht.</b> Es braucht Szenekenntnis und Unterweltkontakte, um ein Treffen zu arrangieren. Sieht das Team mehr wie potenzielle Konsument:innen denn Bedrohung aus, werden Foxys Partner:innen dabei helfen.","sz":9.5,"box":[53.9,443.7,276.6,503.1],"p":101,"i":5,"sec":"foxy-supreme"},{"t":"p","x":"• Wenn ein Treffen anberaumt wird, findet es an einem Ort statt, der vor neugierigen Blicken geschützt ist: unter einer Autobahnbrücke, auf einem Dach, leeren Parkplatz mit Blick auf die Bucht oder in einer verrauchten Gasse.","sz":9.5,"box":[53.9,514.6,278.2,574.1],"p":101,"i":6,"sec":"foxy-supreme"},{"t":"p","x":"• Wenn das Team Foxy überrascht, könnte sie sich im luxuriösen Hotelzimmer oder im <b>Elixier</b>, einer eleganten Bar, aufhalten, die sich beide im als <i>Touristenfalle</i> bekannten Vergnügungsviertel befinden.","sz":9.5,"box":[53.9,582.7,279.5,629.7],"p":101,"i":7,"sec":"foxy-supreme"},{"t":"p","x":"<b>Foxy Supreme ist eine gerissene, anpassungsfähige Gaunerin.</b> Eine Treffen kann mit der gleichen Wahrscheinlichkeit mit ihrer Flucht, nützlichen Informationen oder damit enden, dass einer der SC Kandis nimmt (was zu <u>Auf dem Trip</u> führt). Foxy wird die SC gekonnt einschätzen, alles anbieten, was ihr Herz begehrt, und dabei Mysterien und Identitäten triggern, als gäbe es kein Morgen. Wenn das Team sie zum Reden bringt, erzählt sie viel über die Kandis-Operation.","sz":9.5,"box":[53.9,635.7,285.2,745.1],"p":101,"i":8,"sec":"foxy-supreme"}],"size":[595.276,841.89]},"102":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"FOXY SUPREME","spectra":"","items":[],"box":[142.7,57.5,173.3,69.5],"p":102,"i":0,"sec":"foxy-supreme"},{"t":"p","x":"In der griechischen Mythologie sandten die Götter die Teumessische Füchsin aus, um die Stadt Theben zu verwüsten, indem sie deren Kinder fraß. Sie war nicht zu fangen, und als der Hund, dem niemand entkommen konnte, sie daraufhin jagte, war Zeus gezwungen, das Paradoxon zu verhindern, indem er beide in Stein und dann in ein Sternbild verwandelte.","sz":9.0,"box":[62.4,80.6,277.8,161.6],"p":102,"i":1,"sec":"foxy-supreme"},{"t":"p","x":"Als Riss dieser Geschichte kann sich Foxy Supreme in eine silberne Füchsin von mythischer Größe verwandeln. Es ist unmöglich, sie zu fangen. Sie kann sich jeder Falle oder Fesselung entziehen, und zwar mit Tricks, die von Taschenspielertricks bis zum Durchschreiten von Barrieren oder völligen Verschwinden und Auftauchen an anderer Stelle reichen. Man kann sie verletzen, aber nicht töten, denn das würde bedeuten, dass man sie gefangen hat. Wann immer jemand ihr einen tödlichen Schlag versetzt, muss sie fliehen, ohne es selbst ändern zu können.","sz":9.0,"box":[62.4,170.6,275.6,299.6],"p":102,"i":2,"sec":"foxy-supreme"},{"t":"p","x":"Wenn du Foxys Kräfte einschränken willst, gib ihr ein <i>Paradox 4</i>-Spektrum und <t>Gesetzesbrecherin 1</t>, wenn sie die Immunität gegen <i>Fesseln oder Fangen</i> oder die Aktion <b>Uneinholbar</b> auslöst. Wenn <i>Paradox</i> das Maximum erreicht, erstarren sie und ihre Fänger:in zu Stein, wie beim <b>Paradox des Zeus</b>.","sz":9.0,"box":[62.4,308.6,275.1,377.7],"p":102,"i":3,"sec":"foxy-supreme"},{"t":"p","x":"Foxys Kräfte machen sie immun gegen den Zustand <t>im Käfig</t>, den Risse erhalten, wenn sie die <u>Lebkuchenhaus-Enklave</u> betreten. Da sie sich bisher von dort ferngehalten hat, ist ihr das nicht bewusst.","sz":9.0,"box":[62.4,386.6,275.3,431.6],"p":102,"i":4,"sec":"foxy-supreme"},{"t":"sh","x":"<b>VERLETZEN (ZUR FLUCHT ZWINGEN) 2 / FESSELN ODER FANGEN –</b>","sz":12.0,"box":[62.4,442.1,262.4,466.1],"p":102,"i":5,"sec":"foxy-supreme"},{"t":"p","x":"• <b>Schlau wie ein Fuchs</b>: Wenn Foxy Supreme die Szene betritt, gib ihr <t>der Beute voraus 2</t>.","sz":9.0,"box":[62.4,470.6,261.8,491.6],"p":102,"i":6,"sec":"foxy-supreme"},{"t":"card","x":"<b>Foxy bekommt Kandis von den Hinterlistigen Nagas.</b> Sie weiß, wo das <u>Kandis-Drogenlabor</u> ist, obwohl sie es nicht besucht.","sz":null,"k":"yellow","box":[54.1,552.1,286.6,598.5],"p":102,"i":7,"sec":"foxy-supreme"},{"t":"card","x":"<b>Sie selbst nimmt kein Kandis.</b> Sie weiß, dass Konsument:innen kurzfristig alles Gewünschte bekommen, aber dann die Kräfte verlieren. Sie hat bessere Wege, um zu kriegen, was sie will.","sz":null,"k":"yellow","box":[54.1,607.7,286.6,666.4],"p":102,"i":8,"sec":"foxy-supreme"},{"t":"card","x":"<b>Foxy behält ihre Dealer im Auge, nicht aber deren Kunden, um behaupten zu können, sie kenne sie nicht.</b> Sie weiß nichts von Will, Juan oder Charlie oder woher diese ihr Kandis bekommen haben oder wo sie danach waren.","sz":null,"k":"yellow","box":[54.1,675.6,286.6,747.1],"p":102,"i":9,"sec":"foxy-supreme"},{"t":"p","x":"• <b>Uneinholbar</b>: Wenn Foxy Supreme einen Zustand nimmt, der ihre Freiheit einschränkt oder sie jemandem ausliefert, flieht sie stattdessen (<b>Ihnen etwas verweigern, das sie wollen</b>). • <b>Zuversichtlich</b>: Man kann Foxy nicht mit Drohungen <b>Überzeugen</b>, von denen sie glaubt, dass sie ihr wegen ihres Mythos nichts anhaben können. • <b>Paradox des Zeus</b>: Wenn sie jemand fängt, sind beide bis zum Ende der nächsten Drehpause <t>zu Stein erstarrt 5</t>. • <b>(Als Teumessische Füchsin) Ungeheuerlich</b>: Wenn sie einen Zustand erhält, dem ihre Größe entgegenwirkt, sinkt die Stufe um 2. Wenn die SL mit Foxy eine harte Aktion macht, kann sie zwei Ziele oder ein einzelnes Ziel für +1 Stufe treffen.","sz":9.0,"box":[317.5,83.6,529.5,260.6],"p":102,"i":10,"sec":"foxy-supreme"},{"t":"p","x":"• Herausfinden, was eine Person sich am meisten wünscht, und dann Kandis anbieten, um es zu bekommen (<b>Die Dinge richtig kompliziert machen</b>) • Gereizt die Kleidung zerreißen und in eine riesige Füchsin verwandelt (<b>Die Dinge richtig kompliziert machen</b>), die beißt und kratzt (<t>Risswunden 3</t>) • Sich (als Frau oder Füchsin) aus dem Staub machen und in der Nacht verschwinden (<b>Ihnen etwas verweigern, das sie wollen</b>) • Ein Kind ganz verschlucken (<t>verschluckt 5</t> oder <b>Etwas Schreckliches geschehen lassen</b>) • Jemanden mit ihrem Charme verführen (<t>verführt 2</t>) • Unterweltkontakte zu Hilfe rufen (Neue Bedrohung: Hinterlistige Nagas, S. 104)","sz":9.0,"box":[317.5,269.6,531.7,434.6],"p":102,"i":11,"sec":"foxy-supreme"},{"t":"p","x":"• Jemanden verführerisch von oben bis unten ansehen, wenn er sich ihr nähert • Einfachen Versuchen, sie festzuhalten, ausweichen","sz":9.0,"box":[317.5,443.6,528.9,476.6],"p":102,"i":12,"sec":"foxy-supreme"},{"t":"card","x":"<b>Unter Leckermaul liefen die Dinge anders.</b> Foxy hatte Anweisung, Kund:innen mit hohen Abnahmemengen direkt ins Labor in der alten <u>Aurora-Glashütte</u> zu schicken. Sie hat sie nie wieder gesehen. Seit die neue Version von Kandis da ist, verkaufen sie mehr, aber die Leute nutzen es nicht lange. Das ist nicht gut fürs Geschäft, aber sie kommt damit zurecht.","sz":null,"k":"yellow","box":[309.3,550.9,541.7,659.8],"p":102,"i":13,"sec":"foxy-supreme"},{"t":"card","x":"<b>Foxy und Leckermaul waren Freundinnen,</b> soweit man das in diesem Geschäft überhaupt sein kann. Sie nahm an, dass Leckermaul hinter Kandis steckte. Vor ein paar Wochen brachten die Hinterlistigen Nagas die völlig verwirrte alte Dame zu Foxy. Jemand hat sie aus dem Spiel genommen.","sz":null,"k":"yellow","box":[309.3,669.0,541.7,765.2],"p":102,"i":14,"sec":"foxy-supreme"}],"size":[595.276,841.89]},"103":{"tab":"","blocks":[{"t":"h","x":"DAS KANDIS-DROGENLABOR","sz":16.0,"box":[79.7,68.9,264.6,84.9],"p":103,"i":0,"skip":true,"sec":"das-kandis-drogenlabor"},{"t":"ro","x":"Asiatische Beats dröhnen durch den umgebauten Keller. Man bahnt sich einen Weg vorbei an hängenden Planen, Baustellengittern und ausrangierten Plastikfässern, die nach Chemikalien stinken, bis man schließlich den Hauptraum erreicht. Unter Reihen von Leuchtstoffröhren sitzt ein kleines Heer von Arbeitern an behelfsmäßigen Tischen und arbeitet wie am Fließband daran, Ware herzustellen, zu verarbeiten und zu verpacken. Bewaffnete Wachen sind anwesend. In der Ecke stehen fertige Kisten mit Kandis, deutlich mit dem Buchstaben „K“ gekennzeichnet.","sz":9.0,"box":[62.4,87.3,278.4,236.7],"p":103,"i":1,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"Das Kandis-Drogenlabor befindet sich im umgebauten Keller einer Textilfabrik im Industriegebiet. Die <b>Hinterlistigen Nagas</b>, eine asiatische Straßengang kambodschanischer, vietnamesischer, thailändischer und chinesischer Abstammung, betreibt es. Trotz des mythischen Namens sind die Mitglieder allesamt Schläfer, obwohl einige Laborarbeiter, die lange mit Kandis in Berührung kommen, davon berührt sind.","sz":9.5,"box":[53.9,245.7,276.4,342.7],"p":103,"i":2,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"Dies ist ein guter Ort für Spannung, wenn das Team sich hineinschleicht, oder für Action, wenn es angreift","sz":9.5,"box":[53.9,351.3,281.6,373.3],"p":103,"i":3,"sec":"das-kandis-drogenlabor"},{"t":"threat","stars":"★★","name":"ERWACHTE DROGENKÖCH:INNEN","spectra":"","items":[],"box":[228.0,440.0,248.4,452.0],"p":103,"i":4,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"Das Drogengeschäft ist nicht so glamourös wie Foxy Supremes Lebensstil. Die Arbeiter:innen im Kandis- Labor, darunter junge, aber auch ältere Menschen, arbeiten 18-Stunden-Schichten und kommen mit gefährlichen Chemikalien in Kontakt. Wer längere Zeit mit Kandis zu tun hat, kann erwachen. Die Wirkung ist, dass Kandis beim Probieren die Wünsche erfüllt.","sz":9.0,"box":[62.4,463.1,274.6,544.1],"p":103,"i":5,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"Derzeit gibt es drei solche Mitarbeiter:innen im Labor, und sie verteidigen es mit Grausamkeit derer, die für ihre Träume kämpfen: Es ist ihre Kandis-Quelle.","sz":9.0,"box":[62.4,553.1,275.1,586.1],"p":103,"i":6,"sec":"das-kandis-drogenlabor"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 1 / UM- DREHEN 5 / VORRAT 2</b>","sz":12.0,"box":[62.4,596.7,265.1,620.7],"p":103,"i":7,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• <b>Kandis essen:</b> Wenn man eine Aktion gegen erwachte Kandis-Laborant:innen macht, essen diese Kandis und äußern einen Wunsch (s. S. Harte Aktionen), wenn ihr <i>Vorrat</i> nicht auf dem Maximalwert ist. Für jeden Wunsch bekommen sie bei einer Bedrohungs-Aktion <t>schwindender Vorrat 1</t>.","sz":9.0,"box":[62.4,625.1,276.2,694.1],"p":103,"i":8,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• Die Waffe einer Angreifer:in wegwünschen (alle entsprechenden Stärken verbrennen) • Wünschen, stärker oder unbesiegbar zu sein (Erhöhung des <i>Verletzen- oder Unschädlich machen</i>- Maximums)","sz":9.0,"box":[62.4,703.1,263.8,760.1],"p":103,"i":9,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"oder alles aus dem Ruder läuft. Die Untersuchung ermöglicht es, sich ein Bild von der Kandis-Herstellung zu machen und Hinweise auf die Quelle zu erhalten.","sz":9.5,"box":[309.0,59.9,533.0,94.4],"p":103,"i":10,"sec":"das-kandis-drogenlabor"},{"t":"card","x":"Die Bande holt pro Woche einen Bottich reinen Kandis an der Laderampe der <u>Aurora-Glashütte</u> ab. Dort ist sonst niemand. Es gibt keine Hinweise, dass die Bande dafür bezahlt.","sz":null,"k":"yellow","box":[309.3,112.3,541.7,171.1],"p":103,"i":11,"sec":"das-kandis-drogenlabor"},{"t":"card","x":"Die Bande vertreibt das Endprodukt über das Netzwerk von <u>Foxy Supreme.</u>","sz":null,"k":"yellow","box":[309.3,180.3,541.7,214.0],"p":103,"i":12,"sec":"das-kandis-drogenlabor"},{"t":"card","x":"<b>Die Operation lief ursprünglich über Leckermaul.</b> Vor einem Monat fand die Bande die verwirrte Leckermaul neben dem Bottich mit Kandis an das Gitter gefesselt und einen Zettel, auf dem stand: „Das Geschäft läuft weiter„. Sie brachten sie zu ihrer Freundin Foxy Supreme.","sz":null,"k":"yellow","box":[309.3,223.2,541.7,307.0],"p":103,"i":13,"sec":"das-kandis-drogenlabor"},{"t":"card","x":"Das reine Kandis hier lässt sich leichter auf seine Eigenschaften testen (s. S. Kandis, S. 90).","sz":null,"k":"yellow","box":[309.3,316.2,541.7,362.6],"p":103,"i":14,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• Wünschen, dass ein U-Bahn-Waggon durch die Wand kracht und die Gegner:in trifft (<t>überfahren 4</t>) • Eine überdimensionale Pistole, mit der sie schlecht zielen (<t>Fleischwunde 2</t>), oder ein reich verziertes Katana, das sie schwerfällig führen (<t>böser Schnitt 2</t>) erschaffen • Ein großes Objekt wie z. B. einen Kühlschrank oder eine Tresortür erschaffen und als Deckung benutzen (temporär <t>in Deckung 3</t>) • Wünschen, dass eine Gegner:in mit ihnen tanzt (<t>Tanzwut 3</t>) • Wünschen, dass Stahlketten oder Kaugummi einen Eindringling fesseln (<t>gefesselt 3</t>) oder dass er in die falsche Richtung schaut (temporär <t>verwundbar 2</t>) • Tisch oder Behälter näher heran wünschen, damit sie Kandis nehmen können (entfernt alle Zustände von <i>Vorrat</i> und erhöht das Maximum) • Nach mehr Kandis greifen (entfernt alle Zustände von <i>Vorrat</i>)","sz":9.0,"box":[317.5,463.8,530.1,688.8],"p":103,"i":15,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• Hysterisch lachen, wenn sie die Kandis-Macht entfesseln • Sich ein krasses Outfit wünschen","sz":9.0,"box":[317.5,697.8,530.6,730.8],"p":103,"i":16,"sec":"das-kandis-drogenlabor"}],"size":[595.276,841.89]},"104":{"tab":"","blocks":[{"t":"h","x":"HINTERLISTIGE NAGAS ★★★","sz":12.0,"box":[62.4,57.5,208.6,73.6],"p":104,"i":0,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"Die Hinterlistigen Nagas tragen Cargo- oder Tarnhosen, Sicherheitsschuhe und marineblaue Jacken über beigen Hemden. Sie haben die Hände oft mit Seilen umwickelt und tragen selbstgebastelte Mischungen aus einer Maschinenpistole und einem Tonfa, mit denen sie sowohl im Nahkampf als auch auf Distanz kämpfen können, ohne weitere Waffen ziehen zu müssen. Alle Mitglieder sind in Khmer- oder Thai- Kampfkünsten ausgebildet, meist in Bokator.","sz":9.0,"box":[62.4,80.6,272.9,185.6],"p":104,"i":1,"sec":"das-kandis-drogenlabor"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / BE- DROHEN 3</b>","sz":12.0,"box":[62.4,196.1,264.3,220.1],"p":104,"i":2,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• <b>Kollektiv</b>: Dieses Kollektiv hat mehrere Mitglieder und einen Größenfaktor von 1. • <b>Wache</b>: Wenn hinterlistige Nagas auf der Lauer liegen, gib ihnen <t>aufmerksam 1</t>. • <b>Tonfa-Parade</b>: Wenn sie einen verletzenden oder betäubenden Zustand nehmen, den sie mit einem Tonfa abblocken oder dem sie mit Kampfkunst ausweichen können, sinkt die Stufe um 1.","sz":9.0,"box":[62.4,224.6,276.2,317.6],"p":104,"i":3,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• Maschinenpistolensalve (gib dem Angriff <i>Schwer auszuweichen</i> und dem Ziel eine <t>Schusswunde 3</t>) • Einen Gegner mit einem Tritt (temporär <t>verwundbar 2</t>) einengen und dann einen K.O.- Schlag ausführen (<t>ausgeschlagen Zähne 2</t> oder <t>desorientiert 3</t>) • Nach Hilfe rufen (Größenfaktor +1)","sz":9.0,"box":[62.4,326.6,253.7,419.6],"p":104,"i":4,"sec":"das-kandis-drogenlabor"},{"t":"p","x":"• Die Bokator-Naga-Haltung einnehmen und den Maschinenpistolen-Tonfa schwingen.","sz":9.0,"box":[62.4,428.6,260.5,449.6],"p":104,"i":5,"sec":"das-kandis-drogenlabor"},{"t":"h","x":"HANS‘ LOFT","sz":16.0,"box":[79.7,489.1,157.7,505.1],"p":104,"i":6,"skip":true,"sec":"hans-loft"},{"t":"ro","x":"Hans‘ Loft bietet einen Panoramablick auf eine düstere Industrielandschaft. Statt von Wolkenkratzern ist der offene Raum im obersten Stockwerk von Kühltürmen und verrosteten Silos umgeben, die mit langsam pulsierenden roten Warnleuchten versehen sind. Das Innere des Lofts sähe schick aus, wären da nicht die Reste umgekehrter Hosentaschen und die Wäscheberge auf dem neuen Sofa und der großzügigen modernen Kücheninsel. Der Typ ist ein echter Schlamper, wie zum Teufel kann er sich das alles leisten?","sz":9.0,"box":[62.4,507.5,283.8,646.1],"p":104,"i":7,"sec":"hans-loft"},{"t":"p","x":"Hans Woods ist der Bruder der neuen Lebkuchenhexe Rachel Woods und ihre größte Schwachstelle. Hinter seiner coolen, groovigen DJ-Fassade plagen ihn Schuldgefühle. Er nimmt Kandis, um sich mit dem Leben, das er sich als Straßenkind immer gewünscht hatte, abzulenken. Er fällt auf, weil er der einzige Konsument ist, der verschwand (als Leckermaul ihn und seine Schwester erwischte), aber noch seine Kräfte hat.","sz":9.5,"box":[53.9,655.1,285.4,752.1],"p":104,"i":8,"sec":"hans-loft"},{"t":"p","x":"Egal, ob das Team durch Gerüchte unter Rissen von Hans erfährt oder ob er selbst das Team um Hilfe bittet, die SC können hier landen und versuchen, mehr Informationen zu bekommen oder ihn festzunehmen.","sz":9.5,"box":[309.0,59.9,539.1,106.9],"p":104,"i":9,"sec":"hans-loft"},{"t":"sh","x":"<b>NACHFORSCHUNGEN IM LOFT</b>","sz":10.0,"box":[309.4,120.5,473.4,130.5],"p":104,"i":10,"sec":"hans-loft"},{"t":"card","x":"<b>Offenbar hat jemand vor kurzem das Loft grundsaniert.</b> Vor der Renovierung war es nichts weiter als eine verlassene Müllhalde, eher für Hausbesetzer als für einen Superstar-DJ geeignet. <b>Jenseits des Nebels ist es von Kandis-Wunschzaubern durchdrungen.</b>","sz":null,"k":"yellow","box":[309.3,141.4,541.7,225.2],"p":104,"i":11,"sec":"hans-loft"},{"t":"card","x":"<b>Im Loft gibt es ein Gästezimmer</b>, das der Kleidung im Schrank nach von einer jungen Frau genutzt wurde. Es scheint aktuell unbewohnt zu sein. Da es sich separat ist, nutzt es höchstwahrscheinlich keine Geliebte, sondern eher eine Freundin oder Verwandte. Psychometrie und divinatorische Kräfte können etwas von der Vergangenheit der Geschwister enthüllen und weisen auf die alte <u>Aurora-Glashütte</u> hin.","sz":null,"k":"yellow","box":[309.3,234.4,541.7,355.7],"p":104,"i":12,"sec":"hans-loft"},{"t":"card","x":"<b>Überall liegen Kandis und Kandisverpackungen herum, als hätte Hans einen Riesenvorrat.</b> Dies könnte im Widerspruch zu seinen Behauptungen stehen, er sei zu Leckermauls Haus gekommen, um mehr Kandis zu holen.","sz":null,"k":"yellow","box":[309.3,364.9,541.7,436.0],"p":104,"i":13,"sec":"hans-loft"},{"t":"sh","x":"<b>NACHFORSCHUNGEN ÜBER HANS</b>","sz":10.0,"box":[309.4,449.7,491.2,459.7],"p":104,"i":14,"sec":"hans-loft"},{"t":"p","x":"Hin- und hergerissen zwischen seiner eigenen Schuld und dem Schutz Rachels wird Hans allen direkten Fragen ausweichen. Gib ihm <t>etwas verbergen 2</t> oder <t>dem Thema ausweichen 1</t>, wenn das Team ihm keinen guten Grund gegeben hat, sich zu öffnen. Die folgenden Hinweise zeigen, was Hans weiß, aber nicht unbedingt, was er preiszugeben bereit ist.","sz":9.5,"box":[309.0,465.3,534.1,549.8],"p":104,"i":15,"sec":"hans-loft"},{"t":"card","x":"<b>Hans‘ Schwester Rachel hat das Kandisgeschäft von Leckermaul übernommen,</b> nachdem diese versucht hatte, sie in einen Ofen zu stecken. Hans weiß nicht, was der Ofen macht, nur dass Leckermaul „lebend und hirntot“ herauskam. Rachel hat sich an die Leute, die vorher mit Leckermaul gearbeitet haben, gewandt und leitet den Laden jetzt, aber Hans weiß nicht, wer diese Leute sind.","sz":null,"k":"yellow","box":[309.3,565.9,541.7,687.2],"p":104,"i":16,"sec":"hans-loft"},{"t":"card","x":"Als Hans und Rachel süchtig nach Kandis wurden, wies ihre Dealerin, <u>Foxy Supreme,</u> sie auf die alte <u>Aurora-Glashütte</u> hin, wo „eine magische Tür“ sie in „eine andere Welt“ brachte. Leckermaul sperrte sie in Käfige.","sz":null,"k":"yellow","box":[309.3,696.4,541.7,767.5],"p":104,"i":17,"sec":"hans-loft"}],"size":[595.276,841.89]},"105":{"tab":"","blocks":[{"t":"card","x":"<b>Hans fühlt sich schuldig.</b> Statt sich gegen seine Schwester zu behaupten, wie er es hätte tun sollen, ließ er zu, dass sie mit Hexenkunst etwas von seinen Fähigkeiten nahm und in das Kandis steckte, was Opfer direkt zu ihr führt.","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":105,"i":0,"sec":"hans-loft"},{"t":"card","x":"<b>Hans hält Rachel nicht für böse.</b> Sie ist eine Draufgängerin und Überlebenskünstlerin, die das Beste aus ihrer Situation machen will und der die Hungerjahre auf der Straße nachhängen. <b>Er ist jedoch besorgt, weil sie einige sehr schlimme Dinge getan hat.</b>","sz":null,"k":"yellow","box":[54.1,134.8,286.6,218.6],"p":105,"i":1,"sec":"hans-loft"},{"t":"card","x":"<b>Hans findet immer „nach Hause“ zurück, egal wie sehr er sich verirrt hat.</b> „Heimat“ ist ein Gefühl, das er gegenüber dem Loft und Rachel empfindet, so dass er jederzeit zur <u>Lebkuchenhaus-Enklave</u> reisen kann. Seit er geholfen hat, die Rezeptur zu verbessern, war er nicht mehr dort. <b>Er kann eine weitere Person mitnehmen.</b>","sz":null,"k":"yellow","box":[54.1,227.5,286.6,336.4],"p":105,"i":2,"sec":"hans-loft"},{"t":"h","x":"AUF DEM TRIP","sz":16.0,"box":[78.0,356.1,171.5,372.1],"p":105,"i":3,"skip":true,"sec":"auf-dem-trip"},{"t":"p","x":"Wenn ein SC oder eine Nebenfigur, die Kandis konsumiert haben, mehr wollen, halluzinieren sie eine Spur aus leuchtenden Kieseln, die in die Nacht führt (auch am Tag). Die Spur führt Konsument:innen durch einen Wald von Gebäuden (Hinterhöfe, U-Bahn-Tunnel, Dächer, Kanäle usw.) zur alten <u>Aurora-Glashütte.</u> Dabei sind sie mondsüchtig (wenn du willst: <t>geistig verwirrt 3</t>) und nehmen nur halb wahr, was um sie geschieht.","sz":9.5,"box":[53.9,376.1,286.3,473.1],"p":105,"i":4,"sec":"auf-dem-trip"},{"t":"p","x":"Wenn sich der Charakter auf den Weg zur Süßwarenfabrik macht, kannst du die Szene narrativ einleiten oder die Spieler:in bitten zu erzählen, was der Charakter fühlt und denkt und wie es für ihn war, seine Wünsche Wirklichkeit werden und dann verblassen zu sehen.","sz":9.5,"box":[53.9,481.7,285.3,541.2],"p":105,"i":5,"sec":"auf-dem-trip"},{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[309.0,69.1,377.2,83.1],"p":105,"i":6,"skip":true,"sec":"schicht-3-verloren-im-betondschungel"},{"t":"h","x":"VERLOREN IM BETONDSCHUNGEL","sz":23.0,"box":[309.0,91.4,491.0,142.4],"p":105,"i":7,"skip":true},{"t":"h","x":"DIE ALTE AURORA-GLASHÜTTE","sz":16.0,"box":[334.8,156.0,532.5,172.0],"p":105,"i":8,"skip":true,"sec":"die-alte-aurora-glashuette"},{"t":"ro","x":"Der Weg führt euch durch Gassen und über Straßen, unter Autobahnbrücken und an Kühltürmen vorbei. Er endet jäh an der roten Backsteinmauer einer alten, verlassenen Fabrik, die wahrscheinlich schon seit der Blütezeit der Stadt hier steht. Es herrscht beunruhigende Stille. Nicht weit entfernt sehr ihr ein verrottendes Holztor, verschlossen mit einer Kette, an der ein verblasstes Schild mit „Zutritt verboten“ baumelt. Man sieht spärliches Licht durch die Oberlichter fallen, und eine leere, staubige und mit Betonpfosten gesäumte Halle erhellen. Darin steht ein alter, stillgelegter Industrieofen, dessen Öffnung wie ein fieses Lächeln wirkt.","sz":9.0,"box":[317.5,174.4,538.9,345.4],"p":105,"i":9,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"Die alte Aurora-Glashütte ist ein <i>liminaler Ort</i>, ein Übergangspunkt zwischen der Stadt und der <u>Lebkuchenhaus-Enklave.</u> Die Fabrik ist der einzige Eingang. Allerdings lässt dieser Ort nur diejenigen ein, die Kandis konsumiert haben, also zukünftige Opfer der Lebkuchenhexe (die nach Belieben Zugang gewähren könnte). Die Fabrik dient als Abholplatz für reines Kandis, das die Hinterlistigen Nagas, abholen, und für Ichor aus dem Ofen, den die Mitglieder des Alchemisten-Kultes Magnum Opus bekommen.","sz":9.5,"box":[309.0,354.4,535.6,476.4],"p":105,"i":10,"sec":"die-alte-aurora-glashuette"},{"t":"sh","x":"<b>BETRETEN DER ENKLAVE</b>","sz":10.0,"box":[309.4,490.0,447.2,500.0],"p":105,"i":11,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"<b>Risse, die Kandis konsumiert haben, können die Enklave betreten.</b> Für sie führt jeder Eingang der Fabrik in die Enklave: das Haupttor, eine Hintertür, die Laderampen usw. Es kann sogar ein magischer Durchgang in einer der Außenwände erscheinen. Wer in der verlassenen Fabrik Kandis konsumiert, kann den Weg in die Enklave in der Mitte der Haupthalle, hinter einem Pfosten, in einem Treppenhaus oder gar im alten Ofen finden. <b>Kandis-Konsument:innen merken vielleicht nicht einmal, dass sie die Enklave betreten.</b> Der Durchgang kann für jede Person an einem anderen Ort erscheinen. Wer keinen Zugang zur Enklave hat, sieht die anderen einfach verschwinden.","sz":9.5,"box":[309.0,505.7,541.0,665.1],"p":105,"i":12,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"<b>Ansonsten gibt es keine Zugangsmöglichkeit zur Enklave.</b> Charaktere, die zwischen Dimensionen und Welten wechseln können, müssen <b>Jetzt reicht’s!</b> einsetzen und ein signifikantes Opfer bringen, um allein hinüberzureisen, bzw. ein unumkehrbares, um andere mitzunehmen (die gleiche Einschränkung kann je nach Situation auch für die Rückreise gelten). Alternativ können SC mit der Verbesserung „<b>Kein Berg zu hoch</b>“","sz":9.5,"box":[309.0,673.9,540.7,770.9],"p":105,"i":13,"sec":"die-alte-aurora-glashuette"}],"size":[595.276,841.89]},"106":{"tab":"","blocks":[{"t":"p","x":"des Themas Mobilität einmal pro Spielsitzung in die Enklave reisen, dürfen aber in derselben Spielsitzung nicht mehr zurück und auch niemanden mitnehmen, es sei denn, die SL genehmigt es.","sz":9.5,"box":[53.9,62.5,277.4,109.5],"p":106,"i":0,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"Hans kann einen SC nach dem anderen in die Enklave holen, aber er will konkrete Zusicherungen, dass sie Rachel keinen Schaden zufügen werden. Wenn jemand versucht, ihn geistig zu beeinflussen, löst dies seine Aktion „<b>Wahre Liebe</b>“ aus. Um die Sicherheit seiner Schwester zu gewährleisten, kann er die SC bitten oder durch einen Trick dazu bringen, Kandis zu nehmen. Wenn Charlie dabei ist und merkt, dass ein kontrollierter SC die Enklave nicht betreten kann, wird auch er die betroffene Person zwingen, Kandis zu nehmen.","sz":9.5,"box":[53.9,118.2,284.9,240.2],"p":106,"i":1,"sec":"die-alte-aurora-glashuette"},{"t":"sh","x":"<b>VERLASSEN DER ENKLAVE</b>","sz":10.0,"box":[54.3,253.8,198.6,263.8],"p":106,"i":2,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"<b>Charaktere, die im Ofen verbrannt worden sind, werden aus der Enklave geschleudert</b> und erscheinen in der leeren Fabrik, nachdem sie alle Erinnerungen an ihr Leben als Riss verloren haben oder gerade verlieren, einschließlich der Erlebnisse in der Enklave (dank des Nebels). Andere können die Enklave nur mit Rachels Zustimmung verlassen oder wenn sie die Lebkuchenhexen-Tinktur haben und benutzen, um selbst den Durchgang zu öffnen.","sz":9.5,"box":[53.9,269.4,282.6,378.8],"p":106,"i":3,"sec":"die-alte-aurora-glashuette"},{"t":"sh","x":"<b>NACHFORSCHUNGEN IN DER FABRIK</b>","sz":10.0,"box":[54.3,392.4,254.4,402.4],"p":106,"i":4,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"Das Herumschnüffeln in der Fabrik kann interessante Hinweise liefern, ist aber nicht ungefährlich. Rachel kann von der Enklave aus in die Fabrik spähen und Eindringlinge entdecken. Sie ist nicht immer auf der Hut und zieht es vor, sich zu verstecken und neugierige Personen ins Leere laufen zu lassen, statt ihre Basis zu verraten. Später kann sie die Hinterlistigen Nagas anweisen, die SC zu verfolgen und ihnen eine Lektion zu erteilen. Wenn in der Fabrik etwas passiert, das ein Eingreifen erfordert, oder wenn ein Riss allein hereinspaziert, kann Rachel einen ihrer Lebkuchenmänner (s. S. 110) aussenden, um das Problem zu klären.","sz":9.5,"box":[53.9,408.0,286.1,555.0],"p":106,"i":5,"sec":"die-alte-aurora-glashuette"},{"t":"h","x":"WARUM SO UNEINNEHMBAR?","sz":14.0,"box":[63.3,581.8,201.8,595.8],"p":106,"i":6,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"Die hohe Schwierigkeit des Eindringens in die Enklave dient mehreren Zwecken:","sz":9.0,"box":[63.3,608.4,258.1,629.4],"p":106,"i":7,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"• Die Enklave als Rachels Drogenfestung etablieren • Mehr SC dazu bringen, Kandis zu konsumieren, bevor sie eintreten • Als Barriere für Teams dienen, die von anderen Fällen kommen, so dass sie zuerst diese lösen, bevor sie in die Enklave eindringen.","sz":9.0,"box":[63.3,635.2,270.5,704.2],"p":106,"i":8,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"Je nachdem, welchen cineastischen Effekt du erzielen willst, könnte dies für dein Team leicht sein oder eine Sackgasse, die es zwingt, die Fabrik wochenlang zu überwachen.","sz":9.0,"box":[63.3,710.0,269.1,755.0],"p":106,"i":9,"sec":"die-alte-aurora-glashuette"},{"t":"card","x":"<b>Hier verschwinden Menschen.</b> Will Harris, Juan Delamar, Hans Woods und andere Opfer des Ofens verschwanden für ein oder zwei Tage, bevor sie wieder auftauchten (falls sie es taten). Rosina Leckermaul tauchte vor einem Monat auf. Dies kann man durch einen hervorragenden Geruchssinn, Retrokognition, das Finden eines abgerissenen Stücks Stoff, persönlichen Gegenstands oder Überwachungskameras außerhalb der Fabrik feststellen.","sz":null,"k":"yellow","box":[308.7,54.1,541.2,188.1],"p":106,"i":10,"sec":"die-alte-aurora-glashuette"},{"t":"card","x":"<b>Die Hinterlistigen Nagas holen einmal pro Woche reines Kandis von der Laderampe</b> im hinteren Teil der Fabrik ab. Sie warten eine Weile, dann taucht das Fass einfach auf.","sz":null,"k":"yellow","box":[308.7,197.3,541.2,256.0],"p":106,"i":11,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"<b>Eine Gruppe von Magnum-Opus-Jüngern holt Fässer mit einer schillernden, zähflüssigen Substanz (Ichor) ab und entlädt manchmal Menschen mit verbundenen Augen (Risse) in der Fabrik.</b> Sie kommen spät nachts in einem LKW, den sie rückwärts an die Rampe fahren, um ihre Aktivitäten so gut wie möglich zu verbergen (s. u., <u>Lieferung an Magnum Opus).</u>","sz":10.0,"box":[317.0,270.7,531.5,368.2],"p":106,"i":12,"sec":"die-alte-aurora-glashuette"},{"t":"card","x":"<b>Die Enklave liegt jenseits des Nebels.</b> Risse, die achtsam sind oder Glück haben, können einen vagen Blick auf das erhaschen, was vor sich geht. Risse, die magisch <b>Nachforschungen</b> anstellen (statt den Mythos zu nutzen, um <b>Hinter den Nebel zu schauen</b>), könnten an der Verteidigung der Lebkuchenhexe scheitern.","sz":null,"k":"yellow","box":[308.7,383.0,541.2,479.5],"p":106,"i":13,"sec":"die-alte-aurora-glashuette"},{"t":"p","x":"<b>Weiter jenseits des Nebels</b> gibt es einen schwachen, schon fast vergessenen Hinweis auf eine mächtige dunkle Magie, die dieser Ofen vor vielen Jahren entfesselte: die Scherben von Krystal Knights Teufelsspiegel. Diese Spur kann zur Firma Aurora Glas führen (s. S. <i>Scherben</i>, S. 62), die zur persönlichen Ebene gehört.","sz":10.0,"box":[317.0,494.2,525.8,591.7],"p":106,"i":14,"sec":"die-alte-aurora-glashuette"}],"size":[595.276,841.89]},"107":{"tab":"","blocks":[{"t":"h","x":"LIEFERUNG AN MAGNUM OPUS","sz":16.0,"box":[78.0,452.5,280.7,468.5],"p":107,"i":0,"skip":true,"sec":"lieferung-an-magnum-opus"},{"t":"p","x":"Die folgende Szene steht in Zusammenhang mit den anderen Fällen der mystischen Ebene, <i>Der Kult des Gottkönigs</i> und <i>Der Alchemist</i>. Verwende sie nur, wenn du bereit bist, das Team mit den Ermittlungen in diesen Fällen beginnen zu lassen. Wenn du Fall für Fall leitest, solltest du sie am Ende dieses Falles platzieren.","sz":9.0,"box":[62.4,494.8,280.6,563.8],"p":107,"i":1,"sec":"lieferung-an-magnum-opus"},{"t":"p","x":"<b>Die Fabrik ist ein Knotenpunkt der mystischen Ebene, an dem alle drei Fälle zusammentreffen.</b> Magnum Opus, Armands Kult, braucht den Ofen, um Ichor aus Rissen zu extrahieren, mit dem sie die alchemistische Suche ihres Meisters nach dem Lebenselixier vorantreiben. Einmal im Monat kommen seine Jünger:innen, um Ichor abzuholen und nach <u>Canseliet Manor</u> zu bringen, wo sich Armands Labor befindet (s. S. <i>Der Alchemist</i>). Zusätzlich bringen sie neu erwachte Risse aus den <u>Katakomben</u> (die „Lämmer“, <i>Der Kult des Gottkönigs</i>) mit verbundenen Augen in die Fabrik, um sie im Ofen zu verbrennen. Später lässt man die Opfer frei – sie sollen ihr Leben ohne Mythos-Seele genießen, und Magnum Opus holt den Ichor später ab.","sz":9.5,"box":[53.9,588.4,285.4,760.3],"p":107,"i":2,"sec":"lieferung-an-magnum-opus"},{"t":"p","x":"<b>Jede Lieferung ist für den Kult mit hohem Risiko und maximaler Sicherheit.</b> Eine Gruppe von <b>Armands Jüngern</b> (s. S. <i>Der Alchemist</i>, S. 157) ist mit der Bewachung des LKWs und der Sicherung der Übergabe beschäftigt. Wenn der Kult in Alarmbereitschaft ist und Probleme erwartet oder wenn du die Schwierigkeit erhöhen möchtest, mach aus den <b>Yakuza Yōkai</b> Attentäter:innen, die sich Armand im Austausch für dämonische Kräfte verschrieben haben (s. S. <i>Der Kult des Gottkönigs</i>, S. 122) und den LKW bewachen.","sz":9.5,"box":[309.0,441.0,537.4,562.9],"p":107,"i":3,"sec":"lieferung-an-magnum-opus"},{"t":"p","x":"Die Verfolgung des LKWs oder Sabotage der Übergabe könnte zu einem der anderen Fälle dieser Ebene führen. Diese Szene kann auf den Showdown in der <u>Lebkuchenhaus-Enklave</u> folgen, dann finden eintreffende Magnum-Opus-Kultisten Rachel gestürzt vor, holen den Ichor der SC ab oder beides.","sz":9.5,"box":[309.0,571.6,536.0,643.6],"p":107,"i":4,"sec":"lieferung-an-magnum-opus"}],"size":[595.276,841.89]},"108":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[309.0,69.1,377.2,83.1],"p":108,"i":0,"skip":true,"sec":"schicht-4-die-lebkuchenver-schwoerung"},{"t":"h","x":"DIE LEBKUCHENVER- SCHWÖRUNG","sz":23.0,"box":[309.0,91.4,505.6,142.4],"p":108,"i":1,"skip":true},{"t":"h","x":"LEBKUCHENHAUS-ENKLAVE","sz":16.0,"box":[334.8,156.0,517.8,172.0],"p":108,"i":2,"skip":true,"sec":"lebkuchenhaus-enklave"},{"t":"ro","x":"Seltsamerweise ist das erste, was man in der Fabrik hört, das Knistern brennenden Holzes. Die Fabrik ist dunkel und still, aber sie wirkt nicht mehr verlassen: Ein gedämpftes, warmes Licht flackert an den Wänden. Ihr kommt an einem dunklen Holzpfosten vorbei, der durch jahrelange Abnutzung geglättet ist. Er hinterlässt braune, klebrige Flecken auf euren Händen. Zum ersten Mal bemerkt ihr, dass grobe Stämme die Wellblechdecke über euch tragen. Ein sirupartiger Geruch liegt in der Luft, und in der Nähe hört ihr etwas blubbern. Schließlich tretet ihr in den Schein eines riesigen Ofens und fragt euch, ob es nicht noch mehr ist. In der offenen Tür zeichnet sich die schemenhafte Silhouette eines schlanken Mädchens ab, das in die lodernden Flammen starrt.","sz":9.0,"box":[317.5,174.4,538.9,377.8],"p":108,"i":3,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Die Lebkuchenhaus-Enklave ist das Herzstück der Kandis-Operation und Wohnsitz der neuen Lebkuchenhexe, Rachel Woods. Hier stellt sie Kandis her, und hierher führt es: zu dem Ofen, in dem Mythen ihr Ende finden.","sz":9.5,"box":[309.0,386.8,535.5,446.3],"p":108,"i":4,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Die Enklave ist ein Spiegelbild der Fabrik, in der sie sich befindet, allerdings überlagert vom Mythos des Lebkuchenhauses (ein Haus aus Naschwerk). Die Wände, Balken, Türen und Fenster der Enklave sind eine seltsame Mischung aus Industriebau und Blockhütte. Bei näherer Betrachtung entpuppen sie sich als aus Keksen, Schokolade und Zuckerguss gefertigt – und mit Kandis bedeckt. Das Mobiliar und der flackernde Feuerschein deuten ebenfalls auf den Mythos dieses Ortes hin. Wie bei der Fabrik befindet sich der Ofen im Zentrum der Enklave, ist hier jedoch aktiv und wirkt wie der aus dem Märchen von Hänsel und Gretel. Im hinteren Teil der Enklave lagern Fässer mit reinem Kandis in der Nähe eines großen Kessels, in dem Rachel die Droge kocht. Wer so töricht ist, hier Kandis in zu konsumieren, ist sofort <t>im Käfig 4</t> (ohne <b>Sich der Gefahr zu stellen</b> und ohne Wunscherfüllung).","sz":9.5,"box":[309.0,455.0,538.8,664.6],"p":108,"i":5,"sec":"lebkuchenhaus-enklave"},{"t":"sh","x":"<b>DIE KÄFIGE</b>","sz":10.0,"box":[309.4,678.1,372.5,688.1],"p":108,"i":6,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Kandis-Konsument:innen, die die Enklave betreten, werden von psychedelisch schillernden Lichtern umhüllt, die einen Käfig bilden (<t>im Käfig 4</t>, ohne <b>Sich der Gefahr stellen</b> zu können). Nur sie selbst und andere eingesperrte Personen sehen die leuchtenden Gitterstäbe. Wie ein materieller Käfig schränkt er die","sz":9.5,"box":[309.0,693.6,532.1,765.6],"p":108,"i":7,"sec":"lebkuchenhaus-enklave"}],"size":[595.276,841.89]},"109":{"tab":"","blocks":[{"t":"p","x":"Bewegungsfreiheit der darin befindlichen Person ein, und seine schillernde Energie wirkt dem Einsatz von Mythos-Kräften entgegen. Dieser Zustand betrifft jede Aktion, die darauf abzielt, aus dem Käfig auszubrechen oder auf etwas außerhalb einzuwirken. Auf Versuche von außen wirkt sich der Zustand nicht aus (vorausgesetzt, der Retter ist nicht selbst eingesperrt), es erfordert aber arkanes Wissen, um die Magie aufzuheben, da der Käfig kein Schloss hat und seine „Gitterstäbe“ aus wirbelnder Energie bestehen. Es ist möglich, den Zustand zu reduzieren, man muss ihn aber vollständig entfernen, um einen Charakter zu befreien.","sz":9.5,"box":[53.9,59.9,284.8,206.9],"p":109,"i":0,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Die Trägerin der Lebkuchenhexen-Tinktur – derzeit Rachel Woods – weiß intuitiv, wenn ein Käfig eine Insass:in hat. Sie steuert die Käfige und kann sie in der Halle umher bewegen (als bewege sie ihre Gefangenen telekinetisch), muss dazu allerdings gestikulieren oder mit den Fingern schnippen. Die Gefangenen können sich gegen die Bewegung wehren, indem sie sich durch die „Gitterstäbe“ des Käfigs an etwas festhalten, aber solche Aktionen behindert der Zustand <t>im Käfig</t>.","sz":9.5,"box":[53.9,215.6,284.3,325.1],"p":109,"i":1,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Rachel nutzt die Käfige, um ihre Gefangenen in den Ofen zu schieben.</b> Sobald sie die weiche Aktion dafür gemacht hat, haben die SC ein oder zwei Aktionen, bevor der Käfig und seine Insass:in im Backofen sind, und optional eine weitere, bevor sich die Ofentür schließt. Einen Käfig oder Person darin gegen den Willen der Lebkuchenhexe zu bewegen löst <t>im Käfig</t> aus.","sz":9.5,"box":[53.9,333.9,284.4,418.3],"p":109,"i":2,"sec":"lebkuchenhaus-enklave"},{"t":"sh","x":"<b>IM OFEN</b>","sz":10.0,"box":[54.3,431.9,100.9,441.9],"p":109,"i":3,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Der Ofen, eine gemeinsame Erfindung Armand Kais und der ursprünglichen Lebkuchenhexe, „bäckt“ Risse, um ihre Mythos-Essenz aus ihnen „herauszusaugen„. Das Innere des Ofens besteht aus Industriematerialien und ist schwer zu beschädigen (<i>Zerbrechen 5</i>, alle physischen Schadenszustände reduzieren sich um 2). Die Flammen des Ofens sind kühl und schaden weder Schläfer:innen noch unbelebten Gegenständen, die keine Relikte sind. Wie die Käfige reagiert auch der Ofen auf Gestenbefehle der Trägerin der Lebkuchenhexen-Tinktur.","sz":9.5,"box":[53.9,447.4,283.9,581.9],"p":109,"i":4,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Wenn sich Risse im Ofen befindet, erleiden sie in regelmäßigen Abständen den Zustand</b> <t>Mythosverbrennung 4</t><b>.</b> Während dieses schmerzhaften Prozesses spüren sie, wie ihre Essenz sie verlässt, während um sie herum Funken, Rauch und andere mit ihrem Mythos verbundene Effekte stieben. Je nach Vorstellungen und dem Schwierigkeitsgrad, den du dem Team zumuten möchtest, kann der Ofen diesen Zustand entweder als harte (langsameres Backen, das mehr Möglichkeiten zur Flucht bietet) oder weiche Aktion (schnelles Backen, das extremen Druck erzeugt und möglicherweise schlimme Folgen hat) verleihen. Auf Stufe 6 verwandelt sich der Riss in eine <t>Schläferin mit entzogenem Mythos 6</t>.","sz":9.5,"box":[53.9,590.7,282.1,762.6],"p":109,"i":5,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Bald darauf tropft Ichor aus einem Rohr an der Rückseite des Ofens, schimmert in den Farben des Mythos und strahlt Gefühle, Ideen und psychische Bilder aus dessen Geschichte aus. Zu diesem Zeitpunkt ist der Ichor stabil und passiv, und seine Mythos-Energie lässt sich nicht ohne weiteres aktivieren. Allerdings ist die Substanz äußerst ätzend.","sz":9.5,"box":[309.0,59.9,540.8,144.4],"p":109,"i":6,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Wenn ein Versuch, den Prozess zu unterbrechen, fehlschlägt, insbesondere, während der Riss versucht, <b>Jetzt reicht‘s!</b> einzusetzen und die <t>Mythosverbrennung</t> währenddessen Stufe 6 erreicht, kann er sich in einen Lebkuchenmann statt in eine Schläfer:in verwandeln. Der Ichor der Lebkuchenmänner ist kontaminiert und unbrauchbar, ihr Mythos hat sich verflüchtigt. Niemand hat bisher untersucht, wohin der Mythos dieser armen Seelen entweicht.","sz":9.5,"box":[309.0,153.1,539.2,262.6],"p":109,"i":7,"sec":"lebkuchenhaus-enklave"},{"t":"sh","x":"<b>DIE LEBKUCHENMÄNNER</b>","sz":10.0,"box":[309.4,276.2,448.0,286.2],"p":109,"i":8,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"In den dunklen Nischen der Enklave liegen etwa zwanzig von Rachels Opfern, deren „Backen“ schief ging – die Lebkuchenmänner: verbrannte, knorrige, rostfarbene Wichtel, aus denen neutralweißer Ichor tropft. Ihr Intellekt ist angeschlagen und ihr Körper vom Ofenmythos durchdrungen. Die Lebkuchenmänner reagieren nur auf simple Befehle der Lebkuchenhexe.","sz":9.5,"box":[309.0,291.8,540.0,376.3],"p":109,"i":9,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Rachel setzt sie als zweite Verteidigungslinie ein, falls ungebetene Gäste die Enklave infiltrieren oder ein Riss ausbricht. Wenn sie sie ruft, tauchen die zombieartigen Kreaturen aus den Schatten auf und tun, was sie befiehlt. Wer <b>Heimlichkeit</b> in der Enklave nutzt, kann versehentlich auf sie stoßen.","sz":9.5,"box":[309.0,384.9,540.0,456.9],"p":109,"i":10,"sec":"lebkuchenhaus-enklave"}],"size":[595.276,841.89]},"110":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"DIE LEBKUCHENMÄNNER","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / VER- BRENNEN – / GEIST BEEINFLUSSEN –","items":["<b>Kollektiv</b>: Dieses Kollektiv hat einen Größenfaktor von 1 oder 2.","<b>Geschädigter Intellekt</b>: Wenn jemand versucht, die Lebkuchenmänner zu täuschen, gib ihnen <i>Dumm</i>.","<b>Ichor-Spritzer</b>: Nachdem du die Lebkuchenmänner im Nahkampf besiegt hast, nimm <t>verätzt 2</t>.","Jemanden mit großer Kraft packen und mitschleifen (<t>gepackt 3</t> und <t>verätzt 2</t>)","Unkontrollierte Lebkuchenmänner versuchen, jemanden zu fressen, indem sie ätzenden Ichor auf ihn sabbern (<t>ätzender Biss 3</t>) oder seinen Mythos in den neutralen Ichor saugen (eine Mythos-Stärke verbrennen)","Auf verbrannten Füßen in dunklen Nischen herumschlurfen","Entsetzlich krächzen, wobei Ichor aus ihren offenen Mäulern quillt"],"box":[187.9,57.5,218.5,69.5],"p":110,"i":0,"sec":"lebkuchenhaus-enklave"},{"t":"sh","x":"<b>KONFRONTATION MIT RACHEL WOODS</b>","sz":10.0,"box":[309.4,62.8,522.7,72.8],"p":110,"i":1,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Wenn die SC den Ofen erreichen, arbeitet Rachel Woods dort. Sie könnte Kandis kochen, aber im Idealfall ist sie dabei, einen SC, eine Nebenfigur oder einen beliebten NSC auszubacken.","sz":9.5,"box":[309.0,78.3,536.0,125.3],"p":110,"i":2,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Rachel ist eine zierliche Frau, die ein Gothic-Outfit aus Leder und schwarzer Spitze trägt (den Modegeschmack hat ihr die Lebkuchenhexen-Tinktur beschert). Sie fühlt sich allmächtig und hat alles unter Kontrolle, läuft mit einem Baseballschläger durch die Gegend und isst (normale) Süßigkeiten. Rachel Woods ist selbstbewusst und frech, wie es sich für eine Draufgängerin gehört.","sz":9.5,"box":[309.0,134.0,540.9,231.0],"p":110,"i":3,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Hinter Rachels Strebsamkeit verbirgt sich eine Geschichte.</b> Ähnlich wie ihr alchemistischer Chef, den sie nie kennengelernt hat, läuft Rachel vor etwas davon, in diesem Fall vor ihrer Vergangenheit als Waisenkind, das in Armut lebt. Der Überlebenswille, der ihr durch eine harte Kindheit auf der Straße geholfen hat, leitet sie immer noch, und sie ist überzeugt, dass sie das, was sie tut, für ihr Überleben und das ihres einzigen Angehörigen Hans tut. Sie ist entschlossen, mit dem Ichor-Geschäft so viel Geld zu verdienen, dass sie nie wieder arm sein wird. Dafür musste sie nicht nur jede Gelegenheit ergreifen, sondern auch ihr Herz gegenüber dem Leid der Opfer verschließen.","sz":9.5,"box":[309.0,239.8,540.2,399.2],"p":110,"i":4,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Sie redet sich ein, dass die Verwandlung vielleicht sogar besser für die ehemaligen Risse sei oder „der Preis für den Spaß ist, den sie bei der Erfüllung ihrer Wünsche hatten„. Irgendwann wird sie so böse und verdreht sein wie die ursprüngliche Lebkuchenhexe.","sz":9.5,"box":[309.0,407.8,529.5,467.3],"p":110,"i":5,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Rachel ist hier, um Ichor herzustellen.</b> Es macht für sie keinen Unterschied, ob das Team versucht, sich und andere Risse zu retten, den Ofen zu sabotieren, sie zu Fall zu bringen oder ihre Meinung zu ändern. Wer sich ihr in den Weg stellt, den bäckt oder tötet sie. Die einzige Ausnahme ist Hans, den sie nicht verletzen wird (das verhindert die <b>Wahre Liebe</b>), aber es bedeutet nicht, dass sie tut, was er will. Wenn Hans ihr in die Quere kommt, würde Rachel ihn unschädlich machen, um ihre Aufgabe zu erfüllen.","sz":9.5,"box":[309.0,476.0,540.8,598.0],"p":110,"i":6,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"Gerissene, schlaue oder empfindsame SC könnten Rachels Ambitionen und Traumata herausfinden. Gedankenleser:innen könnten an <b>Verteidigung gegen Magie</b> scheitern.","sz":null,"k":"yellow","box":[309.3,612.6,541.7,671.6],"p":110,"i":7,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"In der Galerie liegen unter Rachels Bett sechs Seesäcke voller Geld, ihre Belohnung für den Ichor, den sie für Magnum Opus geerntet hat.","sz":null,"k":"yellow","box":[309.3,680.5,541.7,726.9],"p":110,"i":8,"sec":"lebkuchenhaus-enklave"}],"size":[595.276,841.89]},"111":{"tab":"","blocks":[{"t":"card","x":"<b>Rachel kennt weder die Leute, die den Ichor sammeln, noch den „Meister„.</b> Ihr ist klar, dass sie hauptsächlich mehr Mythen sammeln soll. Der Versuch, den Ichor-LKW zu überfallen, führt zu <u>Lieferung an Magnum Opus.</u>","sz":null,"k":"yellow","box":[54.1,54.1,286.6,125.6],"p":111,"i":0,"sec":"lebkuchenhaus-enklave"},{"t":"sh","x":"<b>DIE LEBKUCHENHEXEN-TINKTUR</b>","sz":10.0,"box":[54.3,147.7,236.9,158.5],"p":111,"i":1,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"An einer Kette um Rachels Hals hängt eine winzige zylindrische Phiole, nicht länger als ein Finger, die eine karamellfarbene Flüssigkeit enthält: die Lebkuchenhexen-Tinktur. Sie ist die Quelle all ihrer Hexenkräfte. Dank der Verbindung beider Mythen und Armand, der die Tinktur speziell auf sie abgestimmt hat, verfügt Rachel auch über eigene Riss-Kräfte.","sz":9.5,"box":[53.9,164.1,284.5,248.6],"p":111,"i":2,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Folgende Effekte erzeugt die Lebkuchenhexen- Tinktur und bleiben bestehen,</b> selbst wenn Rachel die Flasche verliert:","sz":9.5,"box":[53.9,257.4,274.9,291.8],"p":111,"i":3,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• <b>Kandis</b> sorgt dafür, dass Risse, die die Enklave betreten, in Käfigen landen. • <b>Die Käfige</b> funktionieren normal und setzen ihre Bewegung zum letzten genannten Ziel fort. • <b>Der Ofen</b> brennt weiter oder bleibt aus. • <b>Die Lebkuchenmänner</b> folgen den letzten Befehlen. • <b>Die Enklave</b> bleibt nur für Kandis-Konsument:innen zugänglich.","sz":9.5,"box":[53.9,297.6,285.6,407.1],"p":111,"i":4,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Um etwas davon zu beenden oder zu verändern, muss ein SC oder NSC die Phiole mit der Tinktur an sich bringen und ihre Macht kontrollieren. Für einen Riss- SC erfordert eine kurzfristige Kontrolle einen Einsatz von <b>Jetzt reicht‘s!</b> mit einem signifikanten Opfer. Dies erlaubt es dem SC, den Geschöpfen der Lebkuchenhexe eine Handvoll Befehle zu geben, ehe die Verbindung abbricht. SC mit arkanen Kenntnissen können die <b>Direkte Konfrontation</b> mit dem Lebkuchen-Mythos in der Tinktur suchen, was denselben Effekt hätte.","sz":9.5,"box":[53.9,412.9,286.1,534.9],"p":111,"i":5,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Der Versuch, permanente Kontrolle über die Tinktur zu erlangen, kann ein negatives, neutrales oder positives Ergebnis zeitigen, je nachdem, wie der eigene Mythos mit dem der Lebkuchenhexe interagiert. Mehr zur Aktivierung von Tinkturen s. S. 86.","sz":9.5,"box":[53.9,543.6,285.5,603.1],"p":111,"i":6,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"Die Untersuchung der Lebkuchenhexen-Tinktur zeigt, dass sie aus dem veredelten Ichor Rosina Leckermauls besteht.","sz":null,"k":"yellow","box":[54.1,618.3,286.6,664.7],"p":111,"i":7,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Man kann die <b>Lebkuchenhexen-Tinktur</b> untersuchen, um mehr über Tinkturen generell zu erfahren. Sie kann auf Armands Anwesen hinweisen (s. S. <i>Der Alchemist</i>, S. 155), die Analyse kann einen Abfangversuch der Magnum-Opus-Jünger oder Yakuza-Yokai nach sich ziehen (s. S. <i>Der Kult des Gottkönigs</i>, S. 120).","sz":10.0,"box":[62.4,679.3,277.8,776.8],"p":111,"i":8,"sec":"lebkuchenhaus-enklave"},{"t":"threat","stars":"★★★★","name":"RACHEL","spectra":"VERLETZEN 2 / UNSCHÄDLICH MACHEN 5 / ZUM AUFHÖREN BEWEGEN 6","items":["<b>Draufgängerin</b>: Wenn Rachel die Szene betritt, gib ihr <t>Ehrgeiz 3</t>. Die SL kann diesen Zustand mit einer harten Aktion erneuern.","S<b>chicksale tauschen</b>: Wenn Rachel einen negativen Zustand erhält, der eine Bedrohung für ihren Körper oder Geist darstellt, tauscht sie den Platz mit der Person, die in verleihen will, und wendet das Blatt, so dass diese den Zustand erhält.","<b>Smarter</b>: Wer um Rachel oder in ihre Nähe <b>Heimlichkeit</b> nutzt, erhält <t>bemerkt 3</t>.","<b>Ausgetrickst</b>: In jeder Szene kann die SL drei harte Aktionen als weiche machen, um Rachels Tricks abzubilden.","<b>Verteidigung gegen Magie (Tinktur)</b>: Wenn Rachel durch Magie einen Zustand erleidet, verringert sich die Stufe um 2. Wenn jemand mit Magie <b>Nachforschungen</b> über sie oder die Enklave anstellt, erhält sie <t>geheimnisvoll 2</t>.","<b>Wahre Liebe</b>: Wenn man versucht, Rachel dazu zu bringen, ihren Bruder zu verraten oder zu gefährden, erhält sie <t>wahre Liebe 5</t>.","Sie nutzt die Tinktur, um jemanden in den Käfig zu sperren (<t>im Käfig 3</t>, kann <b>Sich der Gefahr stellen</b>)","Sie verwendet die Tinktur, um sich von Zaubern oder Flüchen zu befreien (3 Stufen entfernen)","Durchschneiden oder Lösen von Fesseln (2 Stufen entfernen)","Sie kann sich Abstand verschaffen, indem sie auf den Ofen klettert, an Ketten durch die Enklave schwingt und von Stegen springt (sie verleiht sich selbst <t>Unerreichbarkeit 2</t> oder <t>Unsichtbarkeit 2</t>)","Mit dem Baseballschläger auf jemanden einschlagen (<t>Atemnot 2</t>) oder mit einem Klappmesser nach jemandem stechen (<t>übler Schnitt 2</t>)","Sie verwendet die Tinktur, um die Käfige, Lebkuchenmänner, den Ofen oder die Enklave zu Steuern.","Stolz sein auf ihre bisherigen „Errungenschaften„"],"box":[358.9,57.5,399.7,69.5],"p":111,"i":9,"sec":"lebkuchenhaus-enklave"}],"size":[595.276,841.89]},"112":{"tab":"","blocks":[{"t":"sh","x":"<b>DIE LEBKUCHENHEXEN-TINKTUR</b>","sz":11.0,"box":[65.2,62.8,246.9,73.8],"p":112,"i":0,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<i>Relikt</i>","sz":10.0,"box":[65.2,83.8,91.2,93.8],"p":112,"i":1,"sec":"lebkuchenhaus-enklave"},{"t":"h","x":"MYSTERIUM","sz":10.0,"box":[65.2,105.3,120.5,115.3],"p":112,"i":2,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Ich frage mich, wie du schmeckst","sz":9.0,"box":[65.2,120.0,198.3,129.0],"p":112,"i":3,"sec":"lebkuchenhaus-enklave"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[65.2,140.8,105.8,150.8],"p":112,"i":4,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"<b><i>Der Ofen</i></b>, <i>In den Ofen locken</i>, <i>Sorglose in Versuchung führen</i>, <i>Dinge süß schmecken lassen</i>, <i>Magische Käfige</i>, <i>Verirrte wittern</i>, <i>Lebkuchenhaus-Enklave</i>, <i>Märchenhafte Hexerei &amp; Alchemie</i>, <i>Lebkuchenmänner</i>, <i>Begrenzte Wunscherfüllung</i>","sz":null,"k":"yellow","box":[65.4,154.4,276.2,212.5],"p":112,"i":5,"sec":"lebkuchenhaus-enklave"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[65.2,224.3,122.1,234.3],"p":112,"i":6,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"<i>Funktioniert nur mit der Phiole</i>, <i>Erhöhte Nebelanfälligkeit</i>, <i>Flüchtige Tinktur</i>, <i>Impulsiv</i>","sz":null,"k":"yellow","box":[65.4,237.9,270.4,260.1],"p":112,"i":7,"sec":"lebkuchenhaus-enklave"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[65.2,271.8,171.9,281.8],"p":112,"i":8,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Herrin der Käfige (einmal pro Szene):</b> Wenn du <b>Heimlichkeit</b> einsetzt, um jemanden in eine Falle zu locken und Stärken aus diesem Thema verwendest, bringst du die Person bei Erfolg dazu, zu stehen, wo du willst. Bei 10+ kannst du ihr außerdem einen geeigneten Fesselungs-Zustand mit Stufe=Kraft geben.","sz":9.0,"box":[65.2,286.5,274.7,355.5],"p":112,"i":9,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"<b>Hexengebräu:</b> Wenn du eine Drehpause nutzt, um deine nächste Aktivität mit diesem Thema vorzubereiten, erhältst du 4 statt 3 Momentum.","sz":9.0,"box":[65.2,367.0,270.9,400.0],"p":112,"i":10,"sec":"lebkuchenhaus-enklave"},{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[300.1,56.4,421.3,82.1],"p":112,"i":11,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles noch einmal zu überdenken gilt:","sz":9.5,"box":[309.0,94.9,537.4,129.4],"p":112,"i":12,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Wie haben sich Team und Nebenfiguren aus dem Ofen befreit? Hat jemand seine Kräfte verloren? Wenn ja, lässt das Team die Person als Schläfer:in leben oder will es herausfinden, ob es eine Rückkehr gibt? Spieler:innen, deren Charaktere ihre Kräfte verloren haben, könnten einen Nebencharakter spielen, der sich diesem Unterfangen anschließt.","sz":9.5,"box":[309.0,140.9,540.4,225.4],"p":112,"i":13,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Was geschah mit dem Ofen? Hat das Team ihn zerstört, abgeschaltet oder in der Enklave zurückgelassen? Was ist mit der Hexen-Tinktur? Viele gefährliche Risse könnten interessiert sein, den Ofen zu reaktivieren und jemandes Existenz als Riss zu beenden oder Kräfte zu stehlen. Vielleicht setzt Armand Kai Rachel wieder als Lebkuchenhexe ein oder findet eine neue, um seine Geschäfte fortzusetzen.","sz":9.5,"box":[309.0,234.0,540.8,331.0],"p":112,"i":14,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Apropos Rachel: Welches Schicksal hat sie erlitten? Hat sie einen Preis für die Selbstinszenierung bezahlt oder ist sie davongekommen? Hat sie Reue gezeigt, und ist Magnum Opus jetzt hinter ihr und ihrer Tinktur her? Was ist mit Hans? Hat seine Schwester ihn in ihre gierigen Machenschaften hineingezogen, oder hat er sich gewehrt? Was wird er tun, wenn er keinen Kandis-Nachschub mehr bekommt?","sz":9.5,"box":[309.0,339.7,541.4,436.7],"p":112,"i":15,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Was ist mit Kandis? Hat es seine Macht behalten oder ist es mit der Hexe verschwunden? Was hindert Risse, süchtig danach zu werden? Bleibt es, könnte es unter Rissen heiße Ware werden und die Wirtschaft der Stadt durcheinanderbringen.","sz":9.5,"box":[309.0,445.4,538.0,504.9],"p":112,"i":16,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Was ist mit den Opfern des Ofens, etwa Will und Juan? Oder Leckermaul? Wird das Team einen Weg finden, ihnen die Kräfte zurückzugeben? Vielleicht wollen sie sie nicht zurück? Wäre es ethisch vertretbar, jemanden ohne Zustimmung wiederzuerwecken? Kann jemand sein Einverständnis geben, wenn ihm ein entscheidender Teil fehlt?","sz":9.5,"box":[309.0,513.5,540.5,598.0],"p":112,"i":17,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Wenn sie kein Produkt mehr haben, was tun die Hinterlistigen Nagas und Foxy Supreme? Werden sie jemanden finden, der eine neue Droge herstellt?","sz":9.5,"box":[309.0,606.7,538.5,641.2],"p":112,"i":18,"sec":"lebkuchenhaus-enklave"},{"t":"p","x":"• Schließlich: Kehren die SC zu The Bowl zurück, nachdem sie den Club und den Riss-Untergrund kennengelernt haben, um sich dort zu entspannen oder mit Gleichgesinnten zu treffen?","sz":9.5,"box":[309.0,649.9,541.0,696.9],"p":112,"i":19,"sec":"lebkuchenhaus-enklave"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":91,"kind":"eisberg","title":"Der Eisberg","file":"img/case04/eisberg.webp","box":[0,0,595,440],"after":null}],"eisberg":{"page":91,"fig":"eisberg","nodes":[{"label":"Hans Woods","layer":0,"x":27.6,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Berichte über eine neue Droge","layer":0,"x":42.8,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Risse verschwinden oder verlieren ihre Kräfte","layer":0,"x":58.3,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Kandis-Konsument:innen","layer":0,"x":80.8,"y":7.9,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Frau Leckermauls Haus","layer":1,"x":22.2,"y":16.5,"w":11,"h":9.5,"target":"frau-leckermauls-haus"},{"label":"Das Schwimmbad","layer":1,"x":35.8,"y":16.1,"w":11,"h":9.5,"target":"das-schwimmbad"},{"label":"The Bowl","layer":1,"x":49.4,"y":15.7,"w":11,"h":9.5,"target":"the-bowl"},{"label":"Will Harris' Wohnung","layer":1,"x":63.9,"y":16.1,"w":11,"h":9.5,"target":"will-harris-wohnung"},{"label":"Charlies Spielzimmer","layer":1,"x":78.9,"y":16.9,"w":11,"h":9.5,"target":"charlies-spielzimmer"},{"label":"Hans' Loft","layer":2,"x":33.0,"y":24.0,"w":11,"h":9.5,"target":"hans-loft"},{"label":"Das Kandis-Drogenlabor","layer":2,"x":45.6,"y":23.6,"w":11,"h":9.5,"target":"das-kandis-drogenlabor"},{"label":"Foxy Supreme","layer":2,"x":58.9,"y":25.1,"w":11,"h":9.5,"target":"foxy-supreme"},{"label":"Auf dem Trip","layer":2,"x":72.2,"y":25.9,"w":11,"h":9.5,"target":"auf-dem-trip"},{"label":"Lieferung an Magnum Opus","layer":3,"x":40.6,"y":32.2,"w":11,"h":9.5,"target":"lieferung-an-magnum-opus"},{"label":"Die alte Aurora-Glashütte","layer":3,"x":57.6,"y":34.6,"w":11,"h":9.5,"target":"die-alte-aurora-glashuette"},{"label":"Lebkuchenhaus","layer":4,"x":49.2,"y":40.8,"w":11,"h":9.5,"target":"lebkuchenhaus-enklave"}]}};
